#include <stdio.h>

int main(void) {
    long long i, j;   /* i += m 可能超过 int；j *= k 可能达到 10^18 */
    if (scanf("%lld %lld", &i, &j) != 2) {
        return 0;
    }
    long long k = i++;   /* 后置：k 取旧值 */
    long long m = ++j;   /* 前置：m 取新值 */
    i += m;
    j *= k;
    i--;
    long long r = j - i;
    printf("i=%lld j=%lld k=%lld m=%lld r=%lld\n", i, j, k, m, r);
    return 0;
}

