#include <stdio.h>

int main(void) {
    unsigned int x, k;
    if (scanf("%u %u", &x, &k) != 2 || k > 31) {
        return 0;
    }
    unsigned int mask = 1u << k;   /* 无符号的 1 左移，k = 31 也是定义良好的 */
    printf("set=%u clear=%u toggle=%u test=%u\n",
           x | mask,          /* 置 1 */
           x & ~mask,         /* 清 0：~mask 只有第 k 位是 0 */
           x ^ mask,          /* 翻转 */
           (x >> k) & 1u);    /* 取出第 k 位，结果只能是 0 或 1 */
    return 0;
}

