#include <stdio.h>

int main(void) {
    unsigned long long n;
    if (scanf("%llu", &n) != 1) {
        return 0;
    }
    /* n & (n-1) 去掉最低位的 1；结果为 0 说明 n 只有一个 1。n = 0 要单独排除 */
    int pow2 = n != 0 && (n & (n - 1)) == 0;
    /* 无符号数的 ~n + 1 按 2^64 回绕，与 n 相与只保留最低位的 1 */
    unsigned long long low = n & (~n + 1);
    printf("%s\n%llu\n", pow2 ? "yes" : "no", low);
    return 0;
}

