#include "binom.h"

long long binom(int n, int k) {
    if (k > n - k) {
        k = n - k;            /* C(n, k) = C(n, n-k)，取较小的 k */
    }
    long long r = 1;
    for (int i = 1; i <= k; i++) {
        /* 循环开始时 r = C(n-k+i-1, i-1)；乘以 (n-k+i) 后一定能被 i 整除，
           结果是 C(n-k+i, i)。中间值最大约 i × C(60,30)，在 long long 范围内 */
        r = r * (n - k + i) / i;
    }
    return r;
}

