int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    int prime = n >= 2;   /* 小于 2 的数都不是质数 */
    /* i <= n / i 与 i * i <= n 等价，但不会发生乘法溢出 */
    for (int i = 2; prime && i <= n / i; i++) {
        if (n % i == 0) {
            prime = 0;
            break;        /* 找到一个因数就可以下结论 */
        }
    }
    printf("%s\n", prime ? "yes" : "no");
    return 0;
}

