#include <stdio.h>

int main(void) {
    int x, count = 0;
    long long sum = 0;
    /* scanf 返回 1 才继续：同时处理了输入结束和非整数两种情况 */
    while (scanf("%d", &x) == 1) {
        if (x == -1) {
            break;               /* 结束标记 */
        }
        if (x < 0 || x > 100) {
            continue;            /* 非法成绩：跳过，继续读下一个 */
        }
        count++;
        sum += x;
    }
    if (count == 0) {
        printf("no data\n");     /* 没有有效成绩时不能做除法 */
        return 0;
    }
    printf("count=%d sum=%lld avg=%.2f\n", count, sum, (double)sum / count);
    return 0;
}

