#include <stdio.h>

int main(void) {
    int a, b;
    if (scanf("%d %d", &a, &b) != 2 || a < 0 || b < 0) {
        return 0;
    }
    int x = a, y = b;          /* 保留原值，辗转相除会改变 x、y */
    while (y != 0) {
        int r = x % y;
        x = y;
        y = r;
    }
    int g = x;
    /* 先除后乘，并在 long long 下进行：a / g * b 不超过最终答案，不会溢出 */
    long long lcm = (g == 0) ? 0 : (long long)a / g * b;
    printf("gcd=%d lcm=%lld\n", g, lcm);
    return 0;
}

