#include <stdio.h>

void print_binary(unsigned int n) {
    if (n >= 2) {
        print_binary(n / 2);   /* 先输出高位（规模更小的问题） */
    }
    printf("%u", n % 2);       /* 再输出最低位：回归阶段输出，顺序正好是从高到低 */
}

int ones(unsigned int n) {
    if (n == 0) {
        return 0;              /* 终止条件 */
    }
    return (int)(n % 2) + ones(n / 2);
}

int main(void) {
    unsigned int n;
    if (scanf("%u", &n) != 1) {
        return 0;
    }
    print_binary(n);
    printf("\n%d\n", ones(n));
    return 0;
}

