        return 0;
    }
    long long x;
    if (scanf("%lld", &x) != 1) {
        return 0;
    }
    /* cur、best 要跨越整个循环保存，所以声明在循环外；用第一个数初始化 */
    long long cur = x, best = x;
    for (int i = 1; i < n; i++) {
        if (scanf("%lld", &x) != 1) {
            return 0;
        }
        cur = (cur + x > x) ? cur + x : x;   /* 接在后面，或者从 x 重新开始 */
        if (cur > best) {
            best = cur;
        }
    }
    printf("%lld\n", best);
    return 0;
}

