    case 3:
        printf("gift 3 x 3\n");
        total += 3;
        /* fall through */
    case 2:
        printf("gift 2 x 2\n");
        total += 2;
        /* fall through */
    case 1:
        printf("gift 1 x 1\n");
        total += 1;
        break;
    default:
        printf("invalid\n");
        return 0;
    }
    printf("total %d\n", total);
    return 0;
}

