#define MAXN 1000

/* 删除 a[0..n-1] 中所有等于 x 的元素，返回剩余元素个数 */
static int remove_value(int a[], int n, int x) {
    int w = 0;                       /* 下一个要写入的位置 */
    for (int i = 0; i < n; i++) {
        if (a[i] != x) {
            a[w] = a[i];
            w++;
        }
    }
    return w;                        /* 新长度由返回值带回调用者 */
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        return 0;
    }

    int a[MAXN];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    int x;
    if (scanf("%d", &x) != 1) {
        return 0;
    }

    int k = remove_value(a, n, x);
    printf("%d\n", k);
    if (k == 0) {
        printf("empty\n");
    } else {
        for (int i = 0; i < k; i++) {
            printf("%d%c", a[i], i + 1 == k ? '\n' : ' ');
        }
    }
    return 0;
}

