#include <stdio.h>

/* 用数组指针接收二维数组：m 指向"4 个 int 的一行" */
void table_sums(int (*m)[4], int rows, long long row_sum[], long long col_sum[4]) {
    for (int j = 0; j < 4; j++) {
        col_sum[j] = 0;                  /* 先清零，再累加 */
    }
    for (int i = 0; i < rows; i++) {
        long long s = 0;
        for (int j = 0; j < 4; j++) {
            s += m[i][j];                /* 第 i 行的和 */
        }
        row_sum[i] = s;
        for (int j = 0; j < 4; j++) {
            col_sum[j] += m[i][j];       /* 第 j 列的和 */
        }
    }
}

int main(void) {
    int rows;
    if (scanf("%d", &rows) != 1 || rows < 1 || rows > 1000) {
        return 0;
    }
    int m[1000][4];
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < 4; j++) {
            if (scanf("%d", &m[i][j]) != 1) {
                return 0;
            }
        }
    }

    long long row_sum[1000];
    long long col_sum[4];
    table_sums(m, rows, row_sum, col_sum);   /* m 退化成 int (*)[4] */

    long long total = 0;
    for (int i = 0; i < rows; i++) {
        printf("row %d: %lld\n", i, row_sum[i]);
        total += row_sum[i];
    }
    for (int j = 0; j < 4; j++) {
        printf("col %d: %lld\n", j, col_sum[j]);
    }
    printf("total: %lld\n", total);
    return 0;
}

