#include <stdio.h>
#include <stdlib.h>

typedef int (*Cmp)(const void *, const void *);

/* 升序：只比大小，绝不做减法（INT_MIN - INT_MAX 会溢出） */
static int cmp_asc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

/* 降序：把升序的结果取反即可 */
static int cmp_desc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x < y) - (x > y);
}

/* 按绝对值升序；绝对值相同则按数值升序 */
static int cmp_abs(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    /* 先转 long long：-INT_MIN 在 int 里会溢出 */
    long long ax = x < 0 ? -(long long)x : x;
    long long ay = y < 0 ? -(long long)y : y;
    if (ax != ay) {
        return ax < ay ? -1 : 1;
    }
    return (x > y) - (x < y);
}

int main(void) {
    int n, mode;
    if (scanf("%d %d", &n, &mode) != 2 || n < 1 || n > 1000) {
        return 0;
    }
    if (mode < 1 || mode > 3) {
        return 0;
    }

    int a[1000];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    /* 规则表：用 mode 选一个函数指针，排序代码只有一份 */
    static const Cmp CMPS[3] = {cmp_asc, cmp_desc, cmp_abs};
    Cmp cmp = CMPS[mode - 1];

    qsort(a, (size_t)n, sizeof a[0], cmp);

    for (int i = 0; i < n; i++) {
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    }
    return 0;
}

