        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    static const Cmp CMPS[3] = {cmp_asc, cmp_desc, cmp_abs};
    qsort(a, (size_t)n, sizeof a[0], CMPS[mode - 1]);
    for (int i = 0; i < n; i++) {
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    }
    return 0;
}

