#include <stdio.h>

#define MAXLEN 60

int main(void) {
    char line[MAXLEN + 2];
    if (fgets(line, sizeof line, stdin) == NULL) {
        return 0;
    }

    /* 1. 求长度，顺便把 fgets 一起读进来的换行符去掉 */
    int len = 0;
    while (line[len] != '\0' && line[len] != '\n') {
        len++;
    }
    line[len] = '\0';

    /* 2. "行首或空格之后"的字母就是单词首字母 */
    int words = 0;
    for (int i = 0; i < len; i++) {
        if (i == 0 || line[i - 1] == ' ') {
            words++;
            if (line[i] >= 'a' && line[i] <= 'z') {
                line[i] = (char)(line[i] - 'a' + 'A');
            }
        }
    }

    printf("%s\n", line);
    printf("%d\n", words);
    return 0;
}

