#include <stdio.h>

#define MAXLEN 50

int main(void) {
    char s[MAXLEN + 2];
    if (fgets(s, sizeof s, stdin) == NULL) {
        return 0;
    }

    int n = 0;
    while (s[n] != '\0' && s[n] != '\n') {
        n++;
    }
    s[n] = '\0';

    /* 先判断回文：反转之后内容就变了，所以趁原样还在时比较 */
    int pal = 1;
    for (int i = 0, j = n - 1; i < j; i++, j--) {
        if (s[i] != s[j]) {
            pal = 0;
            break;
        }
    }

    /* 原地反转：两个下标从两端往中间走，交换到相遇为止 */
    for (int i = 0, j = n - 1; i < j; i++, j--) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
    }

    printf("%s\n", s);
    printf("%s\n", pal ? "YES" : "NO");
    return 0;
}

