#include "stats.h"

long long range_sum(const int *a, int l, int r) {
    long long s = 0;                  /* 必须用 long long：区间和可能到 2×10^12 */
    for (int i = l; i <= r; i++) {    /* 闭区间：i 要取到 r */
        s += a[i];
    }
    return s;
}

int range_min(const int *a, int l, int r) {
    int m = a[l];                     /* 用区间第一个元素初始化，不能是 0 */
    for (int i = l + 1; i <= r; i++) {
        if (a[i] < m) {
            m = a[i];
        }
    }
    return m;
}

