#include <stdio.h>

/* 在只读的有序数组里找 key 第一次出现的位置；找不到返回 -1 */
static int first_index(const int *a, int n, int key) {
    int lo = 0;
    int hi = n;                      /* 答案在 [lo, hi) 这个半开区间里 */
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < key) {
            lo = mid + 1;            /* mid 和它左边都小于 key */
        } else {
            hi = mid;                /* mid 可能是答案，保留它 */
        }
    }
    /* 此时 lo 是第一个 >= key 的位置 */
    if (lo < n && a[lo] == key) {
        return lo;
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    int a[100000];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }
    int q;
    if (scanf("%d", &q) != 1 || q < 1 || q > 1000) {
        return 0;
    }
    for (int i = 0; i < q; i++) {
        int key;
        if (scanf("%d", &key) != 1) {
            return 0;
        }
        printf("%d\n", first_index(a, n, key));
    }
    return 0;
}

