#include "stats.h"

void find_min_max(int *a, int n, int **pmin, int **pmax) {
    int mini = 0, maxi = 0;
    for (int i = 1; i < n; i++) {
        if (a[i] < a[mini]) {
            mini = i;                  /* 严格小于：相同值保留第一次出现 */
        }
        if (a[i] > a[maxi]) {
            maxi = i;
        }
    }
    *pmin = &a[mini];                  /* 写进调用者的指针变量 */
    *pmax = &a[maxi];
}

long long sum_array(int *a, int n) {
    long long s = 0;
    for (int i = 0; i < n; i++) {
        s += a[i];
    }
    return s;
}

