    int n;
    long long target;
    if (scanf("%d %lld", &n, &target) != 2 || n < 1 || n > MAXN) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    int l = 0;
    int r = n - 1;
    const char *ans = "no";
    while (l < r) {
        long long s = (long long)a[l] + a[r];
        if (s == target) {
            ans = "yes";
            break;
        }
        if (s < target) {
            l++;                     /* 和太小：最小的那个数再也用不上了 */
        } else {
            r--;                     /* 和太大：最大的那个数再也用不上了 */
