#include <stdio.h>
#include <string.h>

int main(void) {
    char cmd[16];
    while (scanf("%15s", cmd) == 1) {
        if (strcmp(cmd, "ADD") == 0) {
            int a, b;
            if (scanf("%d %d", &a, &b) != 2) {
                break;
            }
            printf("%d\n", a + b);
        } else if (strcmp(cmd, "MUL") == 0) {
            int a, b;
            if (scanf("%d %d", &a, &b) != 2) {
                break;
            }
            printf("%d\n", a * b);
        } else if (strcmp(cmd, "MAX") == 0) {
            int a, b;
            if (scanf("%d %d", &a, &b) != 2) {
                break;
            }
            printf("%d\n", a > b ? a : b);
        } else if (strcmp(cmd, "GREET") == 0) {
            char name[16];
            if (scanf("%15s", name) != 1) {
                break;
            }
            char line[64];
            strcpy(line, "Hello, ");
            strcat(line, name);
            strcat(line, "!");
            printf("%s\n", line);
        } else if (strcmp(cmd, "LEN") == 0) {
            char text[32];
            if (scanf("%31s", text) != 1) {
                break;
            }
            printf("%zu\n", strlen(text));
        } else if (strcmp(cmd, "CMP") == 0) {
            char x[32], y[32];
            if (scanf("%31s %31s", x, y) != 2) {
                break;
            }
            int c = strcmp(x, y);
            printf("%d\n", c < 0 ? -1 : (c > 0 ? 1 : 0));
        } else {
            printf("ERR\n");
        }
    }
    return 0;
}

