#include <stdio.h>

#define MAXLEN 21
#define MAXRULES 8

int main(void) {
    char word[MAXLEN];
    char kind;
    int n;

    if (scanf("%20s", word) != 1) {
        return 0;
    }
    if (scanf(" %c", &kind) != 1) {
        return 0;
    }
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 0 || n > MAXRULES) {
        return 0;
    }

    char from[MAXRULES], to[MAXRULES];
    for (int k = 0; k < n; k++) {
        char a, b;
        if (scanf(" %c %c", &a, &b) != 2) {
            return 0;
        }
        from[k] = a;
        to[k] = b;
    }

    int len = 0;
    while (word[len] != '\0') {
        len++;
    }

    int total = 0;
    for (int k = 0; k < n; k++) {
        /* 先数一数这一步会命中几个字符：一个都没有 = 一个字节都不用写 */
        int hits = 0;
        for (int i = 0; i < len; i++) {
            if (word[i] == from[k]) {
                hits++;
            }
        }
        if (hits == 0) {
            continue;
        }

        /* 要写了：目标是字面量的话，这一步就是未定义行为 */
        if (kind == 'L') {
            printf("UB %d\n", k + 1);
            return 0;
        }

        for (int i = 0; i < len; i++) {
            if (word[i] == from[k]) {
                word[i] = to[k];   /* from 与 to 相同时也照写不误 */
            }
        }
        total += hits;
    }

    printf("OK %d %s\n", total, word);
    return 0;
}

