/* 找到返回指向第一个匹配元素的指针；找不到返回 NULL */
static int *find_first(int *a, int n, int key) {
    for (int i = 0; i < n; i++) {
        if (a[i] == key) {
            return &a[i];
        }
    }
    return NULL;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }

    int a[1000];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    int q;
    if (scanf("%d", &q) != 1 || q < 1 || q > 1000) {
        return 0;
    }

    for (int i = 0; i < q; i++) {
        int key;
        if (scanf("%d", &key) != 1) {
            return 0;
        }
        int *p = find_first(a, n, key);
        if (p != NULL) {
            printf("%ld\n", (long)(p - a));   /* 指针相减：单位是元素 */
        } else {
            printf("NOT_FOUND\n");
        }
    }
    return 0;
}

