#include <stdio.h>

#define MAX_VARS 200

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 200) {
        return 0;
    }

    int alive[MAX_VARS + 1] = {0};   /* alive[k] == 1 表示变量 k 还活着 */
    int target = 0;                  /* p 指向的变量编号；0 表示还没指向任何变量 */
    int safe = 0, dangling = 0, wild = 0;

    for (int e = 0; e < n; e++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }

        int k = 0;
        if (op == 'D' || op == 'X' || op == 'P') {
            if (scanf("%d", &k) != 1 || k < 1 || k > MAX_VARS) {
                return 0;
            }
        }

        if (op == 'D') {
            alive[k] = 1;
        } else if (op == 'X') {
            alive[k] = 0;          /* 只让变量失效，p 保持不变 */
        } else if (op == 'P') {
            target = k;            /* 只改指向，不影响变量存活 */
        } else if (op == 'U') {
            if (target == 0) {
                printf("WILD\n");
                wild++;
            } else if (alive[target]) {
                printf("SAFE\n");
                safe++;
            } else {
                printf("DANGLING\n");
                dangling++;
            }
        } else {
            return 0;
        }
    }

    printf("SAFE=%d DANGLING=%d WILD=%d\n", safe, dangling, wild);
    return 0;
}

