/* 数组容量：数组长度必须是编译期常量，所以用宏 */
#define STATS_CAP 100000

/* 大额门槛：这里只是声明，定义在 stats.c 里 */
extern const int STATS_TOP;

/* 函数声明：定义都在 stats.c 里 */
