#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

static int g_read_error = 0;

/* 从输入里读下一个数；读不到时把 g_read_error 置 1 */
static int next_number(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) {
        g_read_error = 1;
    }
    return x;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        printf("error\n");
        return 0;
    }

    int best = 0;
    int worst = 0;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            best = next_number();
            worst = best;
            sum += best;
        } else {
            /* TODO: 输入明明够，这里却常常把数字读空。想想宏展开后 next_number() 出现了几次 */
            best = MAX(best, next_number());
            worst = MIN(worst, next_number());
            sum += next_number();
        }
        if (g_read_error) {
            printf("error\n");
            return 0;
        }
    }

    printf("max=%d\nmin=%d\nsum=%d\n", best, worst, sum);
    return 0;
}

