/* 返回一辆车停 hours 小时的费用（元） */
int parking_fee(int hours);

/* 返回 n 辆车（小时数在 hours 数组里）的费用总和 */
int parking_total(const int hours[], int n);

/* 返回 n 辆车中最贵的一单 */
int parking_max(const int hours[], int n);

/* 返回免费（不足 1 小时）的车辆数 */
int parking_free_count(const int hours[], int n);

