void account_init(void);
void account_deposit(int amount);
int account_withdraw(int amount);
long long account_balance(void);
/* ================================================= */

/* 余额是整个程序共享的一份状态：定义在文件作用域，全程序只有这一份 */
static long long g_balance = 0;

void account_init(void) {
    g_balance = 0;
}

void account_deposit(int amount) {
    g_balance += amount;
}

int account_withdraw(int amount) {
    if (amount > g_balance) {
        return 0;                    /* 余额不足：不动余额，返回 0 */
    }
    g_balance -= amount;
    return 1;
}

long long account_balance(void) {
    return g_balance;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        printf("error\n");
        return 0;
    }

    account_init();
    int failed = 0;
    for (int i = 0; i < n; i++) {
        char op = 0;
        int amount = 0;
        if (scanf(" %c %d", &op, &amount) != 2) {
            printf("error\n");
            return 0;
        }
        if (amount < 1 || amount > 10000) {
            printf("error\n");
            return 0;
        }
        if (op == 'D') {
            account_deposit(amount);
        } else if (op == 'W') {
            if (!account_withdraw(amount)) {
                failed++;
            }
        } else {
            printf("error\n");
            return 0;
        }
    }

    printf("balance=%lld\n", account_balance());
    printf("failed=%d\n", failed);
    return 0;
}

