#include <stdio.h>

#define MAXN 60001

static int head[MAXN];
static int nxt[MAXN];
static int to[MAXN];
static int ecnt;
static int frame_size[MAXN];
static int best_bytes;                 /* TODO: 6×10¹⁰ 用 int 装不下 */
static int best_depth;

static void dfs(int u, int dep, int acc) {
    acc += frame_size[u];
    if (acc > best_bytes) {
        best_bytes = acc;
        best_depth = dep;
    }
    for (int e = head[u]; e != -1; e = nxt[e]) {
        dfs(to[e], dep + 1, acc);      /* TODO: 6 万层的链会把栈撑爆 */
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 60000) {
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        if (scanf("%d", &frame_size[i]) != 1 || frame_size[i] < 1 || frame_size[i] > 1000000) {
            return 0;
        }
        head[i] = -1;
    }
    for (int i = 0; i < n - 1; i++) {
        int p, c;
        if (scanf("%d %d", &p, &c) != 2) {
            return 0;
        }
        to[ecnt] = c;
        nxt[ecnt] = head[p];
        head[p] = ecnt;
        ecnt++;
    }

    dfs(1, 1, 0);
    printf("%d %d\n", best_bytes, best_depth);
    return 0;
}

