hints:
`fib` 的滚动写法（这就是"两个累加器的尾递归"去掉递归之后的样子）：

```c
long long a = 0;          /* fib(0) */
long long b = 1;          /* fib(1) */
for (int i = 0; i < n; i++) {
    long long t = a + b;  /* 新的下一个 */
    a = b;
    b = t;
}
return a;                 /* 循环 n 次后，a 就是 fib(n) */
```

`sum_to` 的死循环风险：`for (long long i = 1; i <= n; i++)` 里如果 `i` 写成 `int`，`n = 10⁶` 也不会溢出（`int` 到 21 亿），但和 `n` 比较时会隐式转换，容易看糊涂——**让循环变量的类型和参数一致**最省心。

reference.tail_lib.c:
#include "tail_lib.h"

long long sum_to(long long n) {
    long long acc = 0;
    for (long long i = 1; i <= n; i++) {
        acc += i;
    }
    return acc;
}

long long fib(int n) {
    long long a = 0;                 /* fib(k) */
    long long b = 1;                 /* fib(k+1) */
    for (int i = 0; i < n; i++) {
        long long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

