/* 按键状态寄存器：真实系统里由中断/硬件修改，所以必须 volatile */
static volatile int g_key_status = 1;      /* 1 = 松开，0 = 按下（低电平有效） */

/* 模拟硬件：外部每过一个采样周期，就把当前电平写进状态寄存器 */
