#include <stdio.h>

static int layout_size(const int *sizes, int n) {
    int used = 0;
    int align = 1;

    for (int i = 0; i < n; i++) {
        int a = sizes[i];
        used = (used + a - 1) / a * a;   /* 先向上取整到 a 的倍数 */
        used += a;                       /* 再放下这个成员 */
        if (a > align) {
            align = a;
        }
    }
    return (used + align - 1) / align * align;   /* 最后取整到最大对齐值 */
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 8) {
        return 0;
    }

    int orig[8];
    int proposed[8];
    int best[8];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &orig[i]) != 1 || orig[i] < 1 || orig[i] > 8) {
            return 0;
        }
        best[i] = orig[i];
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &proposed[i]) != 1 || proposed[i] < 1 || proposed[i] > 8) {
            return 0;
        }
    }

    int m;
    if (scanf("%d", &m) != 1 || m < 1) {
        return 0;
    }

    /* 选择排序：按大小从大到小，得到最优顺序 */
    for (int i = 0; i < n; i++) {
        int maxi = i;
        for (int j = i + 1; j < n; j++) {
            if (best[j] > best[maxi]) {
                maxi = j;
            }
        }
        int tmp = best[i];
        best[i] = best[maxi];
        best[maxi] = tmp;
    }

    int a = layout_size(orig, n);
    int p = layout_size(proposed, n);
    int b = layout_size(best, n);

    printf("orig %d\n", a);
    printf("proposed %d\n", p);
    printf("best %d\n", b);
    printf("saved %d\n", a - b);
    printf("total %lld\n", (long long)m * a);
    printf("total_best %lld\n", (long long)m * b);
    return 0;
}

