code.main.c:
#include <stdio.h>

#define MAXN 1000

typedef struct {
    int x;                     /* 错：10^9 × 3 就装不下了 */
    int y;
} Point;

static void transform(Point *p, int dx, int dy, int k) {
    p->x += dx;
    p->y += dy;
    p->x *= k;
    p->y *= k;
}

static long long floor_div(long long a, long long b) {
    long long q = a / b;
    if (a % b != 0 && a < 0) {
        q--;
    }
    return q;
}

static Point centroid(const Point *a, int n) {
    long long sx = 0;
    long long sy = 0;
    for (int i = 0; i < n; i++) {
        sx += a[i].x;
        sy += a[i].y;
    }
    Point c;
    c.x = (int)floor_div(sx, n);
    c.y = (int)floor_div(sy, n);
    return c;
}

static long long manhattan(Point p, Point c) {
    long long dx = (long long)p.x - c.x;
    long long dy = (long long)p.y - c.y;
    if (dx < 0) {
        dx = -dx;
    }
    if (dy < 0) {
        dy = -dy;
    }
    return dx + dy;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    Point a[MAXN];
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d", &a[i].x, &a[i].y) != 2) {
            return 0;
        }
    }
    int dx;
    int dy;
    int k;
    if (scanf("%d %d", &dx, &dy) != 2) {
        return 0;
    }
    if (scanf("%d", &k) != 1) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        transform(&a[i], dx, dy, k);
    }
    Point c = centroid(a, n);
    for (int i = 0; i < n; i++) {
        printf("P%d %d %d\n", i, a[i].x, a[i].y);
    }
    printf("center %d %d\n", c.x, c.y);
    int q;
    if (scanf("%d", &q) != 1) {
        return 0;
    }
    for (int j = 0; j < q; j++) {
        int idx;
        if (scanf("%d", &idx) != 1) {
            return 0;
        }
        printf("d%d %lld\n", idx, manhattan(a[idx], c));
    }
    return 0;
}

