#include <stdio.h>
#include <stdint.h>

/* 三个成员共享同一块 4 字节：float / 无符号位模式 / 有符号位模式 */
typedef union {
    float f;
    uint32_t u;
    int32_t i;
} FBits;

static const char *classify(uint32_t u) {
    uint32_t e = (u >> 23) & 0xFFu;
    uint32_t m = u & 0x7FFFFFu;
    if (e == 0) {
        return (m == 0) ? "zero" : "subnormal";
    }
    if (e == 255) {
        return (m == 0) ? "inf" : "nan";
    }
    return "normal";
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    for (int k = 0; k < n; k++) {
        float f;
        if (scanf("%f", &f) != 1) {
            return 0;
        }
        FBits b;
        b.f = f;                                  /* 写入 4 个字节 */
        printf("f%d bits=%08X sign=%u exp=%u frac=%u as_int=%d class=%s\n",
               k,
               (unsigned)b.u,                     /* 按无符号读同一块内存 */
               (unsigned)((b.u >> 31) & 0x1u),
               (unsigned)((b.u >> 23) & 0xFFu),
               (unsigned)(b.u & 0x7FFFFFu),
               b.i,                               /* 按有符号读同一块内存 */
               classify(b.u));
    }
    return 0;
}

