/* 旧报表模块：金额单位是「元」。与 money.h 的「分」不是一回事，
   所以这里的类型必须换个名字，不能也叫 Money */
typedef int LegacyYuan;

/* 旧报表的取整：四舍五入到最近的 10 元 */
LegacyYuan legacy_round_half_up(LegacyYuan yuan);

#endif

