#include <stdio.h>
#include <stdlib.h>

#define MAXM 5000
#define MAXN 100000

int main(void) {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2 || m < 1 || m > MAXM || n < 0 || n > MAXN) {
        return 0;
    }

    int *diff = calloc((size_t)m + 2, sizeof *diff);   /* m + 2 个 int，全部为 0 */
    if (diff == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        int l, r;
        if (scanf("%d %d", &l, &r) != 2 || l < 1 || r < l || r > m) {
            free(diff);
            diff = NULL;
            return 0;
        }
        diff[l]++;
        diff[r + 1]--;
    }

    int cur = 0;
    int best = 0;
    int first = 0;
    int covered = 0;

    for (int i = 1; i <= m; i++) {
        cur += diff[i];                 /* 前缀和：座位 i 的借用次数 */
        if (cur > best) {
            best = cur;
            first = i;
        }
        if (cur > 0) {
            covered++;
        }
    }

    printf("max=%d\n", best);
    printf("first=%d\n", first);
    printf("covered=%d\n", covered);

    free(diff);
    return 0;
}

