#include <stdio.h>

#define MAX_BLOCKS 205
#define MAX_PTRS 3

/* p → 0，q → 1，r → 2；其他字母返回 -1 */
static int ptr_index(char c) {
    if (c == 'p') {
        return 0;
    }
    if (c == 'q') {
        return 1;
    }
    if (c == 'r') {
        return 2;
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 200) {
        return 0;
    }

    int alive[MAX_BLOCKS] = {0};       /* alive[b] == 1 表示块 b 还活着 */
    int ptr[MAX_PTRS] = {0};           /* ptr[i] == 0 表示这个指针从未被赋值 */
    int next_block = 0;
    int safe = 0, ok = 0, dbl = 0, dangling = 0, wild = 0;

    for (int e = 0; e < n; e++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }

        if (op == 'M') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            next_block++;
            alive[next_block] = 1;
            ptr[i] = next_block;       /* 旧块若还活着，从此再没人指向它 → 泄漏 */
        } else if (op == 'C') {
            char x, y;
            if (scanf(" %c %c", &x, &y) != 2) {
                return 0;
            }
            int ix = ptr_index(x);
            int iy = ptr_index(y);
            if (ix < 0 || iy < 0) {
                return 0;
            }
            ptr[ix] = ptr[iy];         /* 原样复制，包括 0（未初始化）和已释放的块号 */
        } else if (op == 'F') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            int b = ptr[i];
            if (b == 0) {
                printf("FREE %c WILD\n", x);
                wild++;
            } else if (alive[b]) {
                alive[b] = 0;          /* 只改块的状态：所有指向它的指针一起悬垂 */
                printf("FREE %c OK\n", x);
                ok++;
            } else {
                printf("FREE %c DOUBLE\n", x);
                dbl++;
            }
        } else if (op == 'R') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            int b = ptr[i];
            if (b == 0) {
                printf("READ %c WILD\n", x);
                wild++;
            } else if (alive[b]) {
                printf("READ %c SAFE\n", x);
                safe++;
            } else {
                printf("READ %c DANGLING\n", x);
                dangling++;
            }
        } else {
            return 0;
        }
    }

    int leak = 0;
    for (int b = 1; b <= next_block; b++) {
        if (alive[b]) {
            leak++;
        }
    }

    printf("SAFE=%d OK=%d DOUBLE=%d DANGLING=%d WILD=%d LEAK=%d\n",
           safe, ok, dbl, dangling, wild, leak);
    return 0;
}

