#include <stdio.h>

#define MAX_BLOCKS 205
#define MAX_PTRS 2

/* p → 0，q → 1；其他字母返回 -1 */
static int ptr_index(char c) {
    if (c == 'p') {
        return 0;
    }
    if (c == 'q') {
        return 1;
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 200) {
        return 0;
    }

    int alive[MAX_BLOCKS] = {0};       /* alive[b] == 1 表示块 b 还没被释放 */
    int ptr[MAX_PTRS] = {0};           /* 0 表示 NULL */
    int next_block = 0;
    int ub = 0;                        /* 0 表示还没出现 UB，否则是步号 */

    for (int k = 1; k <= n && ub == 0; k++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }

        if (op == 'M') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            next_block++;
            alive[next_block] = 1;
            ptr[i] = next_block;       /* 旧块若仍存活，就再也释放不掉了（泄漏，不是 UB） */
        } else if (op == 'L') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            ptr[i] = 0;
        } else if (op == 'C') {
            char x, y;
            if (scanf(" %c %c", &x, &y) != 2) {
                return 0;
            }
            int ix = ptr_index(x);
            int iy = ptr_index(y);
            if (ix < 0 || iy < 0) {
                return 0;
            }
            ptr[ix] = ptr[iy];
        } else if (op == 'F') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            int b = ptr[i];
            if (b != 0) {              /* 块号 0 是 NULL：free(NULL) 安全 */
                if (!alive[b]) {
                    ub = k;            /* 重复释放 */
                }
                alive[b] = 0;
            }
        } else if (op == 'R' || op == 'W') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            int b = ptr[i];
            if (b == 0 || !alive[b]) { /* 空指针解引用 / 释放后使用 */
                ub = k;
            }
        } else {
            return 0;
        }
    }

    if (ub > 0) {
        printf("UB %d\n", ub);
        return 0;
    }

    int leak = 0;
    for (int b = 1; b <= next_block; b++) {
        if (alive[b]) {
            leak++;
        }
    }
    printf("OK leak=%d\n", leak);
    return 0;
}

