#include <stdio.h>

#define MAX_BLOCKS 205
#define MAX_PTRS 2

static int ptr_index(char c) {
    if (c == 'p') {
        return 0;
    }
    if (c == 'q') {
        return 1;
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 200) {
        return 0;
    }

    int alive[MAX_BLOCKS] = {0};
    int ptr[MAX_PTRS] = {0};
    int next_block = 0;
    int ub = 0;

    for (int k = 1; k <= n && ub == 0; k++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }
        if (op == 'M') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            next_block++;
            alive[next_block] = 1;
            ptr[ptr_index(x)] = next_block;
        } else if (op == 'L') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            ptr[ptr_index(x)] = 0;
        } else if (op == 'C') {
            char x, y;
            if (scanf(" %c %c", &x, &y) != 2) {
                return 0;
            }
            ptr[ptr_index(x)] = ptr[ptr_index(y)];
        } else if (op == 'F') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int b = ptr[ptr_index(x)];
            if (b != 0) {
                if (!alive[b]) {
                    ub = k;
                }
                alive[b] = 0;
            }
        } else if (op == 'R' || op == 'W') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int b = ptr[ptr_index(x)];
            if (b == 0) {              /* 错：只判了空指针，悬垂块被放过 */
                ub = k;
            }
        }
    }

    if (ub > 0) {
        printf("UB %d\n", ub);
        return 0;
    }
    int leak = 0;
    for (int b = 1; b <= next_block; b++) {
        if (alive[b]) {
            leak++;
        }
    }
    printf("OK leak=%d\n", leak);
    return 0;
}

