        int v;
        if (scanf("%d", &v) != 1) {
            stack_destroy(&s);
            return 0;
        }
        if (!stack_push(&s, v)) {
            printf("push_failed=%d\n", i);
            stack_destroy(&s);
            return 0;
        }
    }

    printf("size=%d\n", s.size);
    printf("cap_ok=%d\n", s.cap >= s.size ? 1 : 0);

    long long sum = 0;
    for (int i = 0; i < s.size; i++) {
        sum += s.data[i];
    }
    printf("sum=%lld\n", sum);

    int half = n / 2;
    printf("half=%d\n", half);

    int head = 0;
    long long head_sum = 0;
    printf("pop_head=");
    for (int i = 0; i < half; i++) {
        int v = 0;
        if (!stack_pop(&s, &v)) {
