#include <stdio.h>
#include <stdlib.h>

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);          /* 相减会溢出，这样写最稳 */
}

int main(void) {
    size_t cap = 16;
    size_t n = 0;
    int *a = malloc(cap * sizeof *a);
    if (a == NULL) {
        return 0;
    }

    int v;
    while (scanf("%d", &v) == 1) {
        if (n == cap) {                /* 满了就翻倍 */
            size_t newcap = cap * 2;
            int *tmp = realloc(a, newcap * sizeof *tmp);
            if (tmp == NULL) {
                free(a);
                return 0;
            }
            a = tmp;
            cap = newcap;
        }
        a[n] = v;
        n++;
    }

    printf("count=%zu\n", n);

    long long sum = 0;
    for (size_t i = 0; i < n; i++) {
        sum += a[i];
    }
    printf("sum=%lld\n", sum);

    if (n == 0) {
        printf("avg=0\n");
        printf("median=none\n");
        printf("min=none max=none\n");
    } else {
        printf("avg=%lld\n", sum / (long long)n);
        qsort(a, n, sizeof *a, cmp_int);          /* 中位数对排序后的数据定义 */
        printf("median=%d\n", a[n / 2]);
        printf("min=%d max=%d\n", a[0], a[n - 1]);
    }

    free(a);                                      /* 唯一的释放点：两条路径都经过这里 */
    return 0;
}

