#include "dyn.h"
#include <stdio.h>
#include <stdlib.h>

int *dyn_read(int n) {
    int *a = malloc((size_t)n * sizeof *a);
    if (a == NULL) {
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return NULL;
        }
    }
    return a;
}

long long dyn_sum(const int *a, int n) {
    int s = 0;                    /* 错：10 万 × 10 亿 = 10^14 */
    for (int i = 0; i < n; i++) {
        s += a[i];
    }
    return s;
}

long long dyn_avg(const int *a, int n) {
    return n > 0 ? dyn_sum(a, n) / n : 0;
}

int dyn_max(const int *a, int n) {
    int m = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] > m) {
            m = a[i];
        }
    }
    return m;
}

void dyn_free(int *a) {
    free(a);
}

