#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 16;
    size_t len = 0;
    char *line = malloc(cap);
    if (line == NULL) {
        return 0;
    }

    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (len + 1 >= cap) {                  /* 留一个字节给结尾的 '\0' */
            size_t newcap = cap * 2;
            char *tmp = realloc(line, newcap);
            if (tmp == NULL) {
                free(line);                    /* 失败时 line 仍然有效 */
                return 0;
            }
            line = tmp;
            cap = newcap;
        }
        line[len] = (char)ch;
        len++;
    }
    line[len] = '\0';

    int words = 0;
    int in_word = 0;
    for (size_t i = 0; i < len; i++) {
        if (line[i] == ' ') {
            in_word = 0;
        } else if (!in_word) {
            words++;                           /* 从"空格"或"行首"进入一个词 */
            in_word = 1;
        }
    }

    printf("len=%zu\n", len);
    printf("words=%d\n", words);
    printf("reversed=");
    for (size_t i = len; i > 0; i--) {
        putchar(line[i - 1]);
    }
    putchar('\n');

    free(line);
    return 0;
}

