#include <stdio.h>
#include <string.h>

#define MAXLINE 128

int main(void) {
    char line[MAXLINE] = { 0 };
    if (fgets(line, sizeof line, stdin) == NULL) {
        return 0;
    }
    int n = 0;
    if (sscanf(line, "%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    for (int k = 0; k < n; k++) {
        if (fgets(line, sizeof line, stdin) == NULL) {
            return 0;
        }
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';          /* 去掉行尾换行 */
        }
        char *eq = strchr(line, '=');
        if (eq == NULL) {
            printf("BAD %s\n", line);
        } else {
            *eq = '\0';                  /* 判空之后才能改这一行 */
            printf("%s -> %s\n", line, eq + 1);
        }
    }
    return 0;
}

