hints:
`andseq` 不能简单地写成 `i += 2`。它等价于"先取出旧值、把 `i` 加 1，再判断旧值是不是 0"：旧值为 0 时只加 1，否则再加 1。用临时变量存旧值是关键：

```c
int old = i;
i = old + 1;
if (old != 0) {
    i = i + 1;
}
```

reference.main.c:
#include <stdio.h>
#include <string.h>

int main(void) {
    int k;
    if (scanf("%d", &k) != 1 || k < 1 || k > 100) {
        return 0;
    }
    int i = 0;
    for (int line = 1; line <= k; line++) {
        char op[16];
        if (scanf("%15s", op) != 1) {
            return 0;
        }
        if (strcmp(op, "set") == 0 || strcmp(op, "add") == 0) {
            int v;
            if (scanf("%d", &v) != 1) {
                return 0;
            }
            if (op[0] == 's') {
                i = v;
            } else {
                i += v;
            }
        } else if (strcmp(op, "inc") == 0) {
            i++;
        } else if (strcmp(op, "dec") == 0) {
            i--;
        } else if (strcmp(op, "comma") == 0) {
            i = i + 1;                    /* i = (i++, i++)：净效果加 1 */
        } else if (strcmp(op, "seqinc") == 0) {
            i = i + 2;                    /* (i++, i++)：两条自增都留下 */
        } else if (strcmp(op, "andseq") == 0) {
            int old = i;
            i = old + 1;                  /* 左边一定求值 */
            if (old != 0) {
                i = i + 1;                /* 只有左边非 0 才求值右边 */
            }
        } else if (strcmp(op, "selfpost") == 0 || strcmp(op, "selfpre") == 0 ||
                   strcmp(op, "idxpost") == 0 || strcmp(op, "argpost") == 0) {
            printf("UB %d\n", line);
            return 0;
        }
    }
    printf("OK %d\n", i);
    return 0;
}

