#include <stdio.h>
#include <string.h>

typedef struct {
    long long w[2];   /* 写次数：下标 0 是 i，1 是 j */
    long long r[2];   /* 读次数 */
    long long bad;    /* 子树内部已经数出来的冲突对数 */
} Info;

static char *toks[400];
static int ntok;
static int pos;

/* 两棵互不排序的子树合并：除了求和，还要数跨子树的冲突对 */
static Info join_unseq(Info a, Info b) {
    Info x;
    x.bad = a.bad + b.bad;
    for (int v = 0; v < 2; v++) {
        x.bad += a.w[v] * b.w[v] + a.w[v] * b.r[v] + a.r[v] * b.w[v];
        x.w[v] = a.w[v] + b.w[v];
        x.r[v] = a.r[v] + b.r[v];
    }
    return x;
}

/* 两棵有先后顺序的子树合并：不产生跨子树的冲突 */
static Info join_seq(Info a, Info b) {
    Info x;
    x.bad = a.bad + b.bad;
    for (int v = 0; v < 2; v++) {
        x.w[v] = a.w[v] + b.w[v];
        x.r[v] = a.r[v] + b.r[v];
    }
    return x;
}

static Info parse_one(void) {
    Info x;
    memset(&x, 0, sizeof x);
    if (pos >= ntok) {
        return x;
    }
    const char *t = toks[pos++];
    if (strcmp(t, "i") == 0) {
        x.r[0] = 1;
    } else if (strcmp(t, "j") == 0) {
        x.r[1] = 1;
    } else if (strcmp(t, "pi") == 0) {
        x.r[0] = 1;
        x.w[0] = 1;
    } else if (strcmp(t, "pj") == 0) {
        x.r[1] = 1;
        x.w[1] = 1;
    } else if (strcmp(t, "qi") == 0) {
        x.w[0] = 1;
    } else if (strcmp(t, "qj") == 0) {
        x.w[1] = 1;
    } else if (strcmp(t, "+") == 0 || strcmp(t, "*") == 0 || strcmp(t, "f") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        return join_unseq(a, b);
    } else if (strcmp(t, ",") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        return join_seq(a, b);
    } else if (strcmp(t, "?") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        Info c = parse_one();
        return join_seq(join_seq(a, b), c);
    }
    return x;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    char line[1024];
    if (fgets(line, sizeof line, stdin) == NULL) {   /* 吃掉第一行剩下的换行 */
        return 0;
    }
    for (int k = 0; k < n; k++) {
        if (fgets(line, sizeof line, stdin) == NULL) {
            return 0;
        }
        line[strcspn(line, "\r\n")] = '\0';
        ntok = 0;
        pos = 0;
        for (char *t = strtok(line, " "); t != NULL && ntok < 400; t = strtok(NULL, " ")) {
            toks[ntok++] = t;
        }
        Info r = parse_one();
        if (r.bad > 0) {
            printf("UB %lld\n", r.bad);
        } else {
            printf("CLEAN\n");
        }
    }
    return 0;
}

