#include <stdio.h>
#include <string.h>

typedef struct {
    long long w[2];
    long long r[2];
    long long bad;
} Info;

static char *toks[400];
static int ntok;
static int pos;

static Info join_unseq(Info a, Info b) {
    Info x;
    x.bad = 0;                        /* 错：丢掉了 a.bad 和 b.bad */
    for (int v = 0; v < 2; v++) {
        x.bad += a.w[v] * b.w[v] + a.w[v] * b.r[v] + a.r[v] * b.w[v];
        x.w[v] = a.w[v] + b.w[v];
        x.r[v] = a.r[v] + b.r[v];
    }
    return x;
}

static Info join_seq(Info a, Info b) {
    Info x;
    x.bad = 0;
    for (int v = 0; v < 2; v++) {
        x.w[v] = a.w[v] + b.w[v];
        x.r[v] = a.r[v] + b.r[v];
    }
    return x;
}

static Info parse_one(void) {
    Info x;
    memset(&x, 0, sizeof x);
    if (pos >= ntok) {
        return x;
    }
    const char *t = toks[pos++];
    if (strcmp(t, "i") == 0) {
        x.r[0] = 1;
    } else if (strcmp(t, "j") == 0) {
        x.r[1] = 1;
    } else if (strcmp(t, "pi") == 0) {
        x.r[0] = 1;
        x.w[0] = 1;
    } else if (strcmp(t, "pj") == 0) {
        x.r[1] = 1;
        x.w[1] = 1;
    } else if (strcmp(t, "qi") == 0) {
        x.w[0] = 1;
    } else if (strcmp(t, "qj") == 0) {
        x.w[1] = 1;
    } else if (strcmp(t, "+") == 0 || strcmp(t, "*") == 0 || strcmp(t, "f") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        return join_unseq(a, b);
    } else if (strcmp(t, ",") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        return join_seq(a, b);
    } else if (strcmp(t, "?") == 0) {
        Info a = parse_one();
        Info b = parse_one();
        Info c = parse_one();
        return join_seq(join_seq(a, b), c);
    }
    return x;
}

