        }
        line[strcspn(line, "\r\n")] = '\0';
        ntok = 0;
        pos = 0;
        for (char *t = strtok(line, " "); t != NULL && ntok < 400; t = strtok(NULL, " ")) {
            toks[ntok++] = t;
        }
        Info r = parse_one();
        printf(r.bad > 0 ? "UB %lld\n" : "CLEAN\n", r.bad);
    }
    return 0;
}

