#include <stdio.h>
#include <string.h>

#define MAXN 200

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        return 0;
    }
    char word[MAXN][24];        /* 去重后的字面量，按首次出现顺序 */
    int times[MAXN];            /* 每个字面量出现了几次 */
    int uniq = 0;
    int raw = 0;

    for (int k = 0; k < n; k++) {
        char s[24];
        if (scanf("%23s", s) != 1) {
            return 0;
        }
        raw += (int)strlen(s) + 1;
        int found = -1;
        for (int i = 0; i < uniq; i++) {
            if (strcmp(word[i], s) == 0) {      /* 按内容比较，不能用 == */
                found = i;
                break;
            }
        }
        if (found >= 0) {
            times[found]++;
        } else {
            strcpy(word[uniq], s);
            times[uniq] = 1;
            uniq++;
        }
    }

    int pooled = 0;
    for (int i = 0; i < uniq; i++) {
        pooled += (int)strlen(word[i]) + 1;
    }
    printf("raw %d\n", raw);
    printf("pooled %d\n", pooled);
    printf("saved %d\n", raw - pooled);
    printf("unique %d\n", uniq);

    for (int i = 0; i < uniq; i++) {
        char rev[24];
        int len = (int)strlen(word[i]);
        for (int k = 0; k < len; k++) {
            rev[k] = word[i][len - 1 - k];      /* 从副本里倒着取字符 */
        }
        rev[len] = '\0';
        printf("%d %s\n", times[i], rev);
    }
    return 0;
}

