    memset(mem, 0, sizeof mem);
    if (strcmp(kind, "arr") == 0) {
        int len = (int)strlen(text);
        for (int k = 0; k < len && k < cap; k++) {
            mem[k] = (unsigned char)text[k];
        }
    }

    for (int k = 1; k <= q; k++) {
        char op[8];
        if (scanf("%7s", op) != 1) {
            return 0;
        }
        if (strcmp(op, "p") == 0) {
            if (strcmp(kind, "arr") != 0) {
                printf("S %s\n", text);          /* 字面量：永远是原样 */
