                int end = 0;
                while (end < cap && mem[end] != 0) {
                    end++;
                }
                printf("S ");
                for (int i = 0; i < end; i++) {
                    putchar(mem[i]);
                }
                if (end == cap) {
                    printf(" no-nul");           /* 整个数组里都没有 '\0' */
                }
                printf("\n");
