#include <stdio.h>
#include <string.h>

#define MAXK 6

static int size_of(const char *type) {
    if (strcmp(type, "char") == 0) {
        return 1;
    }
    if (strcmp(type, "short") == 0) {
        return 2;
    }
    if (strcmp(type, "int") == 0) {
        return 4;
    }
    if (strcmp(type, "longlong") == 0) {
        return 8;
    }
    return 0;
}

int main(void) {
    int k = 0;
    int r = 0;
    if (scanf("%d %d", &k, &r) != 2) {
        return 0;
    }
    if (k < 1 || k > MAXK || r < 0 || r > 3) {
        return 0;
    }

    char type[MAXK][16];
    int size[MAXK];
    int offset[MAXK];
    int used = 0;
    int align = 1;
    for (int i = 0; i < k; i++) {
        if (scanf("%15s", type[i]) != 1) {
            return 0;
        }
        size[i] = size_of(type[i]);
        if (size[i] == 0) {
            return 0;
        }
        used = (used + size[i] - 1) / size[i] * size[i];   /* 向上取整到对齐要求 */
