#include <stdint.h>
#include <stdio.h>

typedef struct {
    int32_t id;
    int32_t value;
} Sample;

int main(void) {
    int threshold = 0;
    if (scanf("%d", &threshold) != 1) {
        return 0;
    }

    FILE *in = fopen("samples.bin", "rb");     /* 二进制记录：必须带 b */
    if (in == NULL) {                          /* 打不开：只写错误统计 */
        FILE *fp = fopen("summary.txt", "w");
        if (fp == NULL) {
            return 0;
        }
        fprintf(fp, "status error\ntotal 0\nkept 0\nsum 0\n");
        if (fclose(fp) != 0) {
            return 0;
        }
        return 0;
    }

    FILE *out = fopen("valid.bin", "wb");
    if (out == NULL) {
        fclose(in);
        return 0;
    }

    long total = 0;
    long kept = 0;
    long long sum = 0;
    Sample rec;
    while (fread(&rec, sizeof rec, 1, in) == 1) {   /* 返回值是元素个数 */
        total++;
        if (rec.value < threshold) {
            continue;                                /* 有符号比较；不合格的记录跳过 */
        }
        if (fwrite(&rec, sizeof rec, 1, out) != 1) {
            fclose(out);
            fclose(in);
            return 0;
        }
        kept++;
        sum += rec.value;
    }
    if (fclose(out) != 0) {
        fclose(in);
        return 0;
    }
    fclose(in);

    FILE *fp = fopen("summary.txt", "w");
    if (fp == NULL) {
        return 0;
    }
    fprintf(fp, "status ok\ntotal %ld\nkept %ld\nsum %lld\n", total, kept, sum);
    if (fclose(fp) != 0) {
        return 0;
    }
    return 0;
}

