#include <stdio.h>
#include <string.h>

int main(void) {
    char data[64];
    if (fgets(data, sizeof data, stdin) == NULL) {
        return 0;
    }
    data[strcspn(data, "\r\n")] = '\0';
    size_t len = strlen(data);
    if (len < 1 || len > 40) {
        return 0;
    }

    int q = 0;
    if (scanf("%d", &q) != 1 || q < 1 || q > 40) {
        return 0;
    }

    FILE *fp = fopen("probe.bin", "wb");
    if (fp == NULL) {
        return 1;
    }
    if (fputs(data, fp) == EOF) {
        fclose(fp);
        return 1;
    }
    if (fclose(fp) != 0) {
        return 1;
    }

    fp = fopen("probe.bin", "rb");
    if (fp == NULL) {
        return 1;
    }

    for (int i = 0; i < q; i++) {
        char op[16];
        if (scanf("%15s", op) != 1) {
            fclose(fp);
            return 0;
        }
        if (strcmp(op, "tell") == 0) {
            printf("tell pos=%ld\n", ftell(fp));
        } else if (strcmp(op, "rewind") == 0) {
            rewind(fp);
            printf("rewind pos=%ld\n", ftell(fp));
        } else if (strcmp(op, "seek") == 0) {
            int offset = 0;
            int whence = 0;
            if (scanf("%d %d", &offset, &whence) != 2 || whence < 0 || whence > 2) {
                fclose(fp);
                return 0;
            }
            int base = (whence == 0) ? SEEK_SET : (whence == 1) ? SEEK_CUR : SEEK_END;
            int rc = fseek(fp, (long)offset, base);
            printf("seek %s pos=%ld\n", rc == 0 ? "ok" : "fail", ftell(fp));
        } else if (strcmp(op, "read") == 0) {
            int n = 0;
            if (scanf("%d", &n) != 1 || n < 1 || n > 16) {
                fclose(fp);
                return 0;
            }
            unsigned char bytes[16];
            int got = 0;
            for (int k = 0; k < n; k++) {
                int c = fgetc(fp);
                if (c == EOF) {
                    break;
                }
                bytes[got++] = (unsigned char)c;
            }
            printf("read %d", got);
            for (int k = 0; k < got; k++) {
                printf(" %02X", bytes[k]);
            }
            if (got < n) {
                printf(" eof");
            }
            printf("\n");
        } else {
            fclose(fp);
            return 0;
        }
    }

    printf("final pos=%ld\n", ftell(fp));
    fclose(fp);
    return 0;
}

