#include <stdio.h>
#include <string.h>

#define MAX_NAME 24
#define MAX_EXIST 10

enum State { ST_NULL, ST_OPEN, ST_CLOSED };

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 1 || n > 100) {
        return 0;
    }

    int k = 0;
    if (scanf("%d", &k) != 1) {
        return 0;
    }
    if (k < 0 || k > MAX_EXIST) {
        return 0;
    }
    char exist[MAX_EXIST][MAX_NAME];
    for (int i = 0; i < k; i++) {
        if (scanf("%23s", exist[i]) != 1) {
            return 0;
        }
    }

    int state = ST_NULL;
    int errors = 0;
    for (int i = 1; i <= n; i++) {
        char op[8] = {0};
        if (scanf("%7s", op) != 1) {
            return 0;
        }
        const char *result = "";
        if (strcmp(op, "open") == 0) {
            char name[MAX_NAME] = {0};
            if (scanf("%23s", name) != 1) {
                return 0;
            }
            int found = 0;
            for (int j = 0; j < k; j++) {
                if (strcmp(exist[j], name) == 0) {
                    found = 1;
                    break;
                }
            }
            if (found) {
                state = ST_OPEN;
                result = "open";
            } else {
                state = ST_NULL;              /* fopen 失败：返回值 NULL 覆盖了旧指针 */
                result = "null";
            }
        } else if (strcmp(op, "use") == 0) {
            if (state == ST_OPEN) {
                result = "ok";
            } else if (state == ST_NULL) {
                result = "null-deref";
                errors++;
            } else {
                result = "use-after-close";
                errors++;
            }
        } else if (strcmp(op, "close") == 0) {
            if (state == ST_OPEN) {
                state = ST_CLOSED;            /* 指针值不变，只是流没了 */
                result = "ok";
            } else if (state == ST_NULL) {
                result = "fclose-null";
                errors++;
            } else {
                result = "double-close";
                errors++;
            }
        } else if (strcmp(op, "check") == 0) {
            result = (state == ST_NULL) ? "null" : "non-null";
        } else if (strcmp(op, "clear") == 0) {
            state = ST_NULL;
            result = "null";
        } else {
            return 0;
        }
        printf("%d %s -> %s\n", i, op, result);
    }
    printf("errors %d\n", errors);
    if (state == ST_NULL) {
        printf("final null\n");
    } else if (state == ST_OPEN) {
        printf("final open\n");
    } else {
        printf("final closed\n");
    }
    return 0;
}

