#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_Q 100

/* 实参：字面量 / 读 i / 后置自增 / 前置自增 */
typedef struct {
    int kind;       /* 0 = 字面量，1 = 读 i，2 = i++，3 = ++i */
    long long lit;
} Arg;

static int i_value; /* 模拟用的变量 i */

static Arg parse_arg(const char *s) {
    Arg a;
    a.kind = 0;
    a.lit = 0;
    if (strcmp(s, "i") == 0) {
        a.kind = 1;
    } else if (strcmp(s, "i++") == 0) {
        a.kind = 2;
    } else if (strcmp(s, "++i") == 0) {
        a.kind = 3;
    } else {
        a.lit = strtoll(s, NULL, 10);
    }
    return a;
}

static int has_side_effect(Arg a) {
    return a.kind == 2 || a.kind == 3;
}

/* 求值一次，并把副作用写回 i_value */
static long long eval(Arg a) {
    switch (a.kind) {
        case 1:
            return i_value;
        case 2: {
            long long v = i_value;
            i_value += 1;
            return v;
        }
        case 3:
            i_value += 1;
            return i_value;
        default:
            return a.lit;
    }
}

/* 两个实参都访问 i，且至少一个有副作用 → 这一对无序副本冲突 */
static int conflict(Arg a, Arg b) {
    return a.kind != 0 && b.kind != 0 && (has_side_effect(a) || has_side_effect(b));
}

int main(void) {
    int i0;
    int n;
    if (scanf("%d", &i0) != 1 || i0 < 0 || i0 > 1000000) {
        return 0;
    }
    if (scanf("%d", &n) != 1 || n < 1 || n > MAX_Q) {
        return 0;
    }

    int first_ub = 0;
    for (int k = 1; k <= n; k++) {
        char mac[16];
        char t1[16];
        char t2[16];
        if (scanf("%15s %15s", mac, t1) != 2) {
            return 0;
        }
        int two = (strcmp(mac, "SHL") == 0) || (strcmp(mac, "DIV") == 0) || (strcmp(mac, "MAX") == 0);
        if (two && scanf("%15s", t2) != 1) {
            return 0;
        }

        Arg a = parse_arg(t1);
        Arg b;
        b.kind = 0;
        b.lit = 0;
        if (two) {
            b = parse_arg(t2);
        }
        i_value = i0;                       /* 每条查询都从初值开始 */

        const char *ub = NULL;
        long long value = 0;

        if (strcmp(mac, "SQR") == 0) {
            if (has_side_effect(a)) {       /* x1 与 x2 无序，同一个实参 */
                ub = "unsequenced";
            } else {
                long long v = eval(a);
                long long p = v * v;
                if (p > INT_MAX) {
                    ub = "overflow";
                } else {
                    value = p;
                }
            }
        } else if (strcmp(mac, "SCALE") == 0) {
            long long p = eval(a) * 1000;
            if (p < INT_MIN || p > INT_MAX) {
                ub = "overflow";
            } else {
                value = p;
            }
        } else if (strcmp(mac, "SHL") == 0) {
            if (conflict(a, b)) {
                ub = "unsequenced";
            } else {
                long long x = eval(a);
                long long s = eval(b);
                if (s < 0 || s > 31 || x < 0 || (x << s) > INT_MAX) {
                    ub = "shift";
                } else {
                    value = x << s;
                }
            }
        } else if (strcmp(mac, "DIV") == 0) {
            if (conflict(a, b)) {
                ub = "unsequenced";
            } else {
                long long x = eval(a);
                long long y = eval(b);
                if (y == 0) {
                    ub = "divzero";
                } else if (x == INT_MIN && y == -1) {
                    ub = "overflow";
                } else {
                    value = x / y;          /* C 的整除：向零取整 */
                }
            }
        } else {                            /* MAX：a1→a2、b1→b2 有序，a2/b2 互斥 */
            if (conflict(a, b)) {
                ub = "unsequenced";
            } else {
                long long x = eval(a);      /* a1 */
                long long y = eval(b);      /* b1 */
                value = (x > y) ? eval(a) : eval(b);   /* 只求值被选中的分支 */
            }
        }

        if (ub != NULL) {
            printf("UB %s\n", ub);
            if (first_ub == 0) {
                first_ub = k;
            }
        } else {
            printf("OK %lld\n", value);
        }
    }

    if (first_ub == 0) {
        printf("first-ub=none\n");
    } else {
        printf("first-ub=%d\n", first_ub);
    }
    return 0;
}

