#include <stdio.h>
#include <string.h>

#define LINE_MAX 256

int main(void) {
    char path[128] = {0};
    if (scanf("%127s", path) != 1) {
        return 0;
    }

    FILE *in = fopen(path, "r");
    if (in == NULL) {                       /* 打不开：只写 stats.txt */
        FILE *st = fopen("stats.txt", "w");
        if (st == NULL) {
            return 0;
        }
        fprintf(st, "status error\nlines 0\nlongest 0\n");
        if (fclose(st) != 0) {
            return 0;
        }
        return 0;
    }

    FILE *numbered = fopen("numbered.txt", "w");
    if (numbered == NULL) {
        fclose(in);
        return 0;
    }

    char buf[LINE_MAX];
    int lines = 0;
    size_t longest = 0;
    while (fgets(buf, sizeof buf, in) != NULL) {
        size_t len = strlen(buf);
        while (len > 0 && (buf[len - 1] == '\n' || buf[len - 1] == '\r')) {
            buf[--len] = '\0';              /* 去掉行尾换行（含 \r\n 的情况） */
        }
        lines++;
        if (len > longest) {
            longest = len;
        }
        if (fprintf(numbered, "%03d|%s\n", lines, buf) < 0) {
            fclose(numbered);
            fclose(in);
            return 0;
        }
    }
    if (fclose(numbered) != 0) {
        fclose(in);
        return 0;
    }
    fclose(in);

    FILE *st = fopen("stats.txt", "w");
    if (st == NULL) {
        return 0;
    }
    fprintf(st, "status ok\nlines %d\nlongest %zu\n", lines, longest);
    if (fclose(st) != 0) {
        return 0;
    }
    return 0;
}

