long log_emit(const char *level, const char *message) {
    int out = fprintf(stdout, "[%s] %s\n", level, message);
    if (out < 0) {
        return -1;
    }
    int err = fprintf(stderr, "%s: %s\n", level, message);
    if (err < 0) {
        return -1;
    }
    if (fflush(stdout) != 0) {
        return -1;
    }
    if (fflush(stderr) != 0) {
        return -1;
    }
    return (long)out + err;
}

