#include <stdio.h>
#include <string.h>
#include "logapi.h"

static void strip_eol(char *s) {
    s[strcspn(s, "\r\n")] = '\0';
}

int main(void) {
    char level[32];
    char message[128];
    if (fgets(level, sizeof level, stdin) == NULL) {
        return 0;
    }
    strip_eol(level);
    if (fgets(message, sizeof message, stdin) == NULL) {
        return 0;
    }
    strip_eol(message);

    /* 把 stderr 接到文件上，这样驱动可以把它读回来摊给学习者看 */
    if (freopen("err.log", "w", stderr) == NULL) {
        return 2;
    }

    long n = log_emit(level, message);
    fflush(stdout);
    fflush(stderr);

    printf("ret %ld\n", n);
    printf("---stderr---\n");

    FILE *fp = fopen("err.log", "r");
    if (fp == NULL) {
        return 3;
    }
    char line[256];
    while (fgets(line, sizeof line, fp) != NULL) {
        fputs(line, stdout);
    }
    fclose(fp);
    return 0;
}

