#include <stdio.h>

static long file_size(const char *path) {
    FILE *fp = fopen(path, "rb");
    if (fp == NULL) {
        return -1;
    }
    if (fseek(fp, 0, SEEK_END) != 0) {
        fclose(fp);
        return -1;
    }
    long n = ftell(fp);
    fclose(fp);
    return n;
}

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1 || n < 0 || n > 100) {
        return 0;
    }

    FILE *log = fopen("audit.log", "w");
    if (log == NULL) {
        return 1;
    }

    long written = 0;
    for (int i = 1; i <= n; i++) {
        int id = 0;
        int value = 0;
        if (scanf("%d %d", &id, &value) != 2) {
            fclose(log);
            return 0;
        }
        if (fprintf(log, "%d %d\n", id, value) < 0) {
            fclose(log);
            return 1;
        }
        if (fflush(log) != 0) {                 /* 关键：不刷新，读取方看不到 */
            fclose(log);
            return 1;
        }
        written = ftell(log);
        long visible = file_size("audit.log");
        if (visible == written) {
            printf("ok %d %ld\n", i, written);
        } else {
            printf("miss %d %ld\n", i, visible);
        }
    }

    printf("records %d total %ld\n", n, written);
    fclose(log);
    return 0;
}

