                crlf++;
                total++;                       /* CRLF 的两个字节都算进总字节数 */
            } else {
                cr++;
                if (next != EOF) {
                    ungetc(next, fp);          /* 退回去，下一轮继续处理 */
                }
            }
        } else if (c == '\n') {
            lf++;
        }
        c = fgetc(fp);
    }
    if (fclose(fp) != 0) {
        return 1;
    }

    const char *style;
    if (total == 0) {
        style = "empty";
    } else if (crlf == 0 && lf == 0 && cr == 0) {
        style = "none";
    } else if (crlf > 0 && lf == 0 && cr == 0) {
        style = "crlf";
    } else if (crlf == 0 && cr == 0 && lf > 0) {
        style = "lf";
    } else {
        style = "mixed";
    }

    printf("bytes %ld\n", total);
    printf("crlf %ld\n", crlf);
    printf("lf %ld\n", lf);
    printf("cr %ld\n", cr);
    printf("style %s\n", style);
    return 0;
}

