    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &input[i]) != 1) {
            return 0;
        }
    }

    Bst t;
    bst_init(&t);
    printf("init_empty=%d\n", (t.root == NULL && t.size == 0) ? 1 : 0);

