    int fails = 0;
    for (int i = 0; i < n; i++) {
        int r = bst_insert(&t, input[i]);
        if (r == 0) {
            dupes++;
        } else if (r < 0) {
            fails++;
            break;
        }
    }
    printf("insert_fail=%d\n", fails);
    printf("size=%d\n", t.size);
    printf("dupes=%d\n", dupes);

