#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_MAX 16

typedef struct Song {
    int id;
    char name[NAME_MAX];
    struct Song *prev;
    struct Song *next;
} Song;

typedef struct {
    Song *head;
    Song *tail;
    int count;
} Playlist;

static void pl_init(Playlist *L) {
    L->head = NULL;
    L->tail = NULL;
    L->count = 0;
}

static Song *make_song(int id, const char *name) {
    Song *s = malloc(sizeof *s);
    if (s == NULL) {
        return NULL;
    }
    s->id = id;
    strncpy(s->name, name, sizeof s->name - 1);
    s->name[sizeof s->name - 1] = '\0';
    s->prev = NULL;
    s->next = NULL;
    return s;
}

static int pl_append(Playlist *L, int id, const char *name) {
    Song *s = make_song(id, name);
    if (s == NULL) {
        return 0;
    }
    s->prev = L->tail;
    if (L->tail != NULL) {
        L->tail->next = s;
    } else {
        L->head = s;               /* 空表：新节点同时是头 */
    }
    L->tail = s;
    L->count++;
    return 1;
}

/* 插到 pos 之后；pos == NULL 表示插到表头 */
static int pl_insert(Playlist *L, Song *pos, int id, const char *name) {
    Song *s = make_song(id, name);
    if (s == NULL) {
        return 0;
    }
    if (pos == NULL) {
        s->next = L->head;
        if (L->head != NULL) {
            L->head->prev = s;
        } else {
            L->tail = s;           /* 空表：新节点也是尾 */
        }
        L->head = s;
        L->count++;
        return 1;
    }
    s->prev = pos;                 /* ① */
    s->next = pos->next;           /* ② 读的是旧后继 */
    if (pos->next != NULL) {
        pos->next->prev = s;       /* ③ 旧后继回头 */
    } else {
        L->tail = s;               /*    pos 原来是尾巴 */
    }
    pos->next = s;                 /* ④ 最后才断开旧连接 */
    L->count++;
    return 1;
}

static Song *pl_find(Playlist *L, int id) {
    for (Song *p = L->head; p != NULL; p = p->next) {
        if (p->id == id) {
            return p;
        }
    }
    return NULL;
}

static int pl_remove(Playlist *L, Song *s) {
    if (s == NULL) {
        return 0;
    }
    if (s->prev != NULL) {
        s->prev->next = s->next;
    } else {
        L->head = s->next;         /* 删的是头节点 */
    }
    if (s->next != NULL) {
        s->next->prev = s->prev;
    } else {
        L->tail = s->prev;         /* 删的是尾节点 */
    }
    free(s);
    L->count--;
    return 1;
}

static void print_forward(const Playlist *L) {
    printf("forward %d", L->count);
    for (const Song *p = L->head; p != NULL; p = p->next) {
        printf(" %d:%s", p->id, p->name);
    }
    printf("\n");
}

static void print_backward(const Playlist *L) {
    printf("backward %d", L->count);
    for (const Song *p = L->tail; p != NULL; p = p->prev) {
        printf(" %d:%s", p->id, p->name);
    }
    printf("\n");
}

static int pl_destroy(Playlist *L) {
    int freed = 0;
    Song *p = L->head;
    while (p != NULL) {
        Song *next = p->next;      /* 先存 next */
        free(p);
        p = next;
        freed++;
    }
    L->head = NULL;
    L->tail = NULL;
    L->count = 0;
    return freed;
}

int main(void) {
    Playlist L;
    pl_init(&L);

    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 300) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        int id;
        char name[NAME_MAX];
        if (scanf("%d %15s", &id, name) != 2) {
            pl_destroy(&L);
            return 0;
        }
        if (!pl_append(&L, id, name)) {
            pl_destroy(&L);
            return 0;
        }
    }

    int m;
    if (scanf("%d", &m) != 1 || m < 0 || m > 100) {
        pl_destroy(&L);
        return 0;
    }
    for (int i = 0; i < m; i++) {
        int after;
        int id;
        char name[NAME_MAX];
        if (scanf("%d %d %15s", &after, &id, name) != 3) {
            break;
        }
        Song *pos = (after == 0) ? NULL : pl_find(&L, after);
        if (after != 0 && pos == NULL) {
            continue;                  /* 数据保证不会发生 */
        }
        if (!pl_insert(&L, pos, id, name)) {
            break;
        }
    }

    int k;
    if (scanf("%d", &k) != 1 || k < 0 || k > 100) {
        pl_destroy(&L);
        return 0;
    }
    int removed = 0;
    for (int i = 0; i < k; i++) {
        int id;
        if (scanf("%d", &id) != 1) {
            break;
        }
        if (pl_remove(&L, pl_find(&L, id))) {
            removed++;
        }
    }

    print_forward(&L);
    print_backward(&L);
    printf("removed=%d\n", removed);

    int freed = pl_destroy(&L);
    printf("freed=%d\n", freed);
    return 0;
}

