        return 0;
    }
    for (int i = 0; i < m; i++) {
        int after;
        int id;
        char name[NAME_MAX];
        if (scanf("%d %d %15s", &after, &id, name) != 3) {
            break;
        }
        Song *pos = (after == 0) ? NULL : pl_find(&L, after);
        if (after != 0 && pos == NULL) {
            continue;
        }
        if (!pl_insert(&L, pos, id, name)) {
            break;
        }
    }

    int k;
    if (scanf("%d", &k) != 1 || k < 0 || k > 100) {
        pl_destroy(&L);
        return 0;
    }
    int removed = 0;
    for (int i = 0; i < k; i++) {
        int id;
        if (scanf("%d", &id) != 1) {
            break;
        }
        if (pl_remove(&L, pl_find(&L, id))) {
            removed++;
        }
    }

    print_forward(&L);
    print_backward(&L);
    printf("removed=%d\n", removed);

    int freed = pl_destroy(&L);
    printf("freed=%d\n", freed);
    return 0;
}

