#include <stdio.h>
#include <stdint.h>

static int is_pow2(unsigned int x) {
    return x != 0u && (x & (x - 1u)) == 0u;
}

static int popcount(unsigned int x) {
    int c = 0;
    while (x != 0u) {
        x &= x - 1u;
        c++;
    }
    return c;
}

static unsigned int lowbit(unsigned int x) {
    return x & (~x + 1u);
}

static unsigned int swap32(unsigned int x) {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8) |
           ((x & 0x00FF0000u) >> 8) |
           ((x & 0xFF000000u) >> 24);
}

static int is_little_endian(void) {
    uint16_t v = 1u;
    return *(const unsigned char *)&v == 1u;
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1 || q < 1 || q > 1000) {
        return 0;
    }

    for (int i = 0; i < q; i++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }
        if (op == 'E') {
            printf("%s\n", is_little_endian() ? "little" : "big");
            continue;
        }

        unsigned int x;
        if (scanf("%u", &x) != 1) {
            return 0;
        }
        if (op == 'P') {
            printf("%d\n", is_pow2(x));
        } else if (op == 'C') {
            printf("%d\n", popcount(x));
        } else if (op == 'L') {
            printf("%08X\n", lowbit(x));
        } else if (op == 'S') {
            printf("%08X\n", swap32(x));
        } else {
            return 0;
        }
    }
    return 0;
}

