#include "text.h"

size_t text_length(const char *s) {
    size_t n = 0;
    while (s[n] != '\0') {
        n++;
    }
    return n;
}

int text_count(const char *s, char c) {
    int cnt = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (s[i] == c) {
            cnt++;
        }
    }
    return cnt;
}

char *text_reverse(char *s) {
    size_t n = text_length(s);
    for (size_t i = 0; i < n / 2; i++) {
        char t = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = t;
    }
    return s;
}

