#include <stdio.h>

#define MEM_SIZE 64

static int find_nul(const unsigned char *mem, int from) {
    for (int i = from; i < MEM_SIZE; i++) {
        if (mem[i] == 0) {
            return i;
        }
    }
    return -1;
}

static int ranges_overlap(int d, int s, int len) {
    if (len <= 0) {
        return 0;
    }
    return d < s + len && s < d + len;
}

int main(void) {
    char line[65];
    if (scanf("%64s", line) != 1) {
        return 0;
    }

    unsigned char mem[MEM_SIZE];
    for (int i = 0; i < MEM_SIZE; i++) {
        mem[i] = (line[i] == '.') ? 0u : (unsigned char)line[i];
    }

    int q;
    if (scanf("%d", &q) != 1 || q < 1 || q > 200) {
        return 0;
    }

    for (int k = 0; k < q; k++) {
        char op[9];
        int d;
        int s;
        if (scanf("%8s %d %d", op, &d, &s) != 3) {
            return 0;
        }
        if (d < 0 || d >= MEM_SIZE || s < 0 || s >= MEM_SIZE) {
            return 0;
        }

        if (op[0] == 's') {                     /* strcpy */
            int nul = find_nul(mem, s);
            if (nul < 0) {
                printf("ub-read\n");
                continue;
            }
            int len = nul - s + 1;              /* 结尾的 '\0' 也要占一个字节 */
            if (d + len > MEM_SIZE) {
                printf("ub-write\n");
                continue;
            }
            if (ranges_overlap(d, s, len)) {
                printf("ub-overlap\n");
                continue;
            }
            for (int i = 0; i < len; i++) {
                mem[d + i] = mem[s + i];
            }
            printf("ok\n");
        } else {
            int n;
            if (scanf("%d", &n) != 1 || n < 0 || n > MEM_SIZE) {
                return 0;
            }
            if (s + n > MEM_SIZE) {
                printf("ub-read\n");
                continue;
            }
            if (d + n > MEM_SIZE) {
                printf("ub-write\n");
                continue;
            }
            if (op[3] == 'c') {                 /* memcpy：不允许重叠 */
                if (ranges_overlap(d, s, n)) {
                    printf("ub-overlap\n");
                    continue;
                }
            }
            unsigned char tmp[MEM_SIZE];
            for (int i = 0; i < n; i++) {
                tmp[i] = mem[s + i];
            }
            for (int i = 0; i < n; i++) {
                mem[d + i] = tmp[i];
            }
            printf("ok\n");
        }
    }
    return 0;
}

