#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int cap = 8;
    int n = 0;
    int *a = malloc((size_t)cap * sizeof *a);
    if (a == NULL) {
        return 0;
    }

    int failed = 0;                /* realloc 失败时置 1，读完后再统一收尾 */
    int x;
    while (scanf("%d", &x) == 1) {
        if (n == cap) {
            int *tmp = realloc(a, (size_t)cap * 2 * sizeof *a);
            if (tmp == NULL) {
                failed = 1;
                break;
            }
            a = tmp;               /* 成功之后才覆盖原指针 */
            cap *= 2;
        }
        a[n++] = x;
    }

    if (!failed) {
        if (n == 0) {
            printf("empty\n");
        } else {
            long long sum = 0;
            int mn = a[0];
            int mx = a[0];
            for (int i = 0; i < n; i++) {
                sum += a[i];
                if (a[i] < mn) {
                    mn = a[i];
                }
                if (a[i] > mx) {
                    mx = a[i];
                }
            }

            printf("count=%d\n", n);
            printf("sum=%lld\n", sum);
            printf("min=%d max=%d\n", mn, mx);
            printf("rev=");
            for (int i = n - 1; i >= 0; i--) {
                printf("%d", a[i]);
                if (i > 0) {
                    printf(" ");
                }
            }
            printf("\n");
        }
    }

    free(a);                       /* 全程序只有这一个出口，不会漏 */
    return 0;
}

