#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int cap = 8;
    int n = 0;
    int *a = malloc((size_t)cap * sizeof *a);
    if (a == NULL) {
        return 0;
    }

    int x;
    while (scanf("%d", &x) == 1) {
        if (n == cap) {
            int *tmp = realloc(a, (size_t)cap * 2 * sizeof *a);
            if (tmp == NULL) {
                free(a);
                return 0;
            }
            a = tmp;
            cap *= 2;
        }
        a[n++] = x;
    }

    if (n == 0) {
        printf("empty\n");
        free(a);
        return 0;
    }

    int sum = 0;                   /* 错：总额最大 5×10^13，int 装不下 */
    int mn = a[0];
    int mx = a[0];
    for (int i = 0; i < n; i++) {
        sum += a[i];
        if (a[i] < mn) {
            mn = a[i];
        }
        if (a[i] > mx) {
            mx = a[i];
        }
    }

    printf("count=%d\n", n);
    printf("sum=%d\n", sum);
    printf("min=%d max=%d\n", mn, mx);
    printf("rev=");
    for (int i = n - 1; i >= 0; i--) {
        printf("%d", a[i]);
        if (i > 0) {
            printf(" ");
        }
    }
    printf("\n");
    free(a);
    return 0;
}

