#include <stdio.h>

#define MAX_OPS 205
#define NULL_PTR 0
#define STACK_PTR (-1)

static int ptr_index(char c) {
    if (c == 'p') {
        return 0;
    }
    if (c == 'q') {
        return 1;
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 200) {
        return 0;
    }

    int alive[MAX_OPS] = {0};
    int ptr[2] = { NULL_PTR, NULL_PTR };
    int next_block = 0;
    int ub = 0;
    const char *kind = "";

    for (int k = 1; k <= n && ub == 0; k++) {
        char op;
        if (scanf(" %c", &op) != 1) {
            return 0;
        }

        if (op == 'M') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            next_block++;
            alive[next_block] = 1;
            ptr[i] = next_block;
        } else if (op == 'L') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            ptr[i] = NULL_PTR;
        } else if (op == 'S') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            ptr[i] = STACK_PTR;
        } else if (op == 'C') {
            char x;
            char y;
            if (scanf(" %c %c", &x, &y) != 2) {
                return 0;
            }
            int ix = ptr_index(x);
            int iy = ptr_index(y);
            if (ix < 0 || iy < 0) {
                return 0;
            }
            ptr[ix] = ptr[iy];
        } else if (op == 'F') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            if (ptr[i] == STACK_PTR) {
                ub = k;
                kind = "invalid-free";
            } else if (ptr[i] != NULL_PTR) {
                if (!alive[ptr[i]]) {
                    ub = k;
                    kind = "double-free";
                } else {
                    alive[ptr[i]] = 0;
                }
            }
        } else if (op == 'R' || op == 'W') {
            char x;
            if (scanf(" %c", &x) != 1) {
                return 0;
            }
            int i = ptr_index(x);
            if (i < 0) {
                return 0;
            }
            if (ptr[i] == NULL_PTR) {
                ub = k;
                kind = "null-deref";
            } else if (ptr[i] != STACK_PTR && !alive[ptr[i]]) {
                ub = k;
                kind = "use-after-free";
            }
        } else {
            return 0;
        }
    }

    if (ub > 0) {
        printf("UB %d %s\n", ub, kind);
        return 0;
    }

    int leak = 0;
    for (int b = 1; b <= next_block; b++) {
        if (alive[b]) {
            leak++;
        }
    }
    printf("OK leak=%d\n", leak);
    return 0;
}

