#include <stdio.h>
#include <string.h>

#define MAXN 500
enum { SEC_DATA, SEC_BSS, SEC_RODATA, SEC_STACK, SEC_HEAP };

typedef struct {
    char name[16];
    int sec;
    int alive;
    int size;              /* 只有堆对象用到 */
} Obj;

static const char *SEC_NAME[] = { "data", "bss", "rodata", "stack", "heap" };

static Obj *find(Obj *tab, int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(tab[i].name, name) == 0) {
            return &tab[i];
        }
    }
    return NULL;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        return 0;
    }

    Obj tab[MAXN];
    int cnt = 0;
    int leaks = 0;
    long long bytes = 0;

    for (int i = 0; i < n; i++) {
        char op[8];
        char name[16];
        if (scanf("%7s", op) != 1) {
            return 0;
        }

        if (strcmp(op, "G") == 0) {
            int init = 0;
            if (scanf("%15s %d", tab[cnt].name, &init) != 2) {
                return 0;
            }
            tab[cnt].sec = init ? SEC_DATA : SEC_BSS;
            tab[cnt].alive = 1;
            tab[cnt].size = 0;
            cnt++;
        } else if (strcmp(op, "C") == 0) {
            if (scanf("%15s", tab[cnt].name) != 1) {
                return 0;
            }
            tab[cnt].sec = SEC_RODATA;
            tab[cnt].alive = 1;
            tab[cnt].size = 0;
            cnt++;
        } else if (strcmp(op, "S") == 0) {
            if (scanf("%15s", tab[cnt].name) != 1) {
                return 0;
            }
            tab[cnt].sec = SEC_BSS;      /* static：静态存储期，不在栈上 */
            tab[cnt].alive = 1;
            tab[cnt].size = 0;
            cnt++;
        } else if (strcmp(op, "E") == 0) {
            if (scanf("%15s", tab[cnt].name) != 1) {
                return 0;
            }
            tab[cnt].sec = SEC_STACK;
            tab[cnt].alive = 1;
            tab[cnt].size = 0;
            cnt++;
        } else if (strcmp(op, "H") == 0) {
            int size = 0;
            if (scanf("%15s %d", tab[cnt].name, &size) != 2) {
                return 0;
            }
            tab[cnt].sec = SEC_HEAP;
            tab[cnt].alive = 1;
            tab[cnt].size = size;
            cnt++;
            leaks++;
            bytes += size;
        } else if (strcmp(op, "L") == 0) {
            if (scanf("%15s", name) != 1) {
                return 0;
            }
            Obj *p = find(tab, cnt, name);
            if (p == NULL) {
                return 0;
            }
            p->alive = 0;                /* 离开作用域：栈对象销毁 */
        } else if (strcmp(op, "F") == 0) {
            if (scanf("%15s", name) != 1) {
                return 0;
            }
            Obj *p = find(tab, cnt, name);
            if (p == NULL) {
                return 0;
            }
            if (!p->alive) {
                printf("double-free %s\n", name);
            } else {
                p->alive = 0;
                leaks--;
                bytes -= p->size;
            }
        } else if (strcmp(op, "P") == 0) {
            if (scanf("%15s", name) != 1) {
                return 0;
            }
            Obj *p = find(tab, cnt, name);
            if (p == NULL) {
                return 0;
            }
            printf("%s %s %s\n", p->name, SEC_NAME[p->sec], p->alive ? "alive" : "dead");
        }
    }

    printf("leak %d %lld\n", leaks, bytes);
    return 0;
}

