statement.description:
三指针反转是链表里最经典的一段代码，也是最容易被"改一行就全乱"的一段：

```c
Node *prev = NULL;
Node *cur = head;
while (cur != NULL) {
    Node *next = cur->next;   /* ① 先存后继 */
    cur->next = prev;         /* ② 掉头 */
    prev = cur;               /* ③ prev 前进 */
    cur = next;               /* ④ cur 前进 */
}
head = prev;
```

请你读入 n 个整数，用 `malloc` 在堆上建一条单链表（**尾插**，保持输入顺序），然后用上面这段代码**原样**反转它。反转过程中，在每一轮循环**刚进入时**（也就是执行任何赋值之前）把三个指针当前指向的节点的值打印出来，最后输出新的表头和反转后的链表。

要求你的程序真的用 `malloc` 建节点、真的按上面四句的顺序反转，并在结束前把每个节点都 `free` 掉。

reference.main.c:
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

/* 打印一个指针：空指针输出 NULL，否则输出它指向的节点的值 */
static void show(const char *label, const Node *p) {
    if (p == NULL) {
        printf("%s=NULL", label);
    } else {
        printf("%s=%d", label, p->value);
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 12) {
        return 0;
    }

    Node *head = NULL;
    Node **link = &head;
    for (int i = 0; i < n; i++) {
        int v;
        if (scanf("%d", &v) != 1) {
            return 0;
        }
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            return 0;
        }
        node->value = v;
        node->next = NULL;
        *link = node;              /* 尾插：link 始终指向"新节点该放的位置" */
        link = &node->next;
    }

    printf("steps=%d\n", n);

    Node *prev = NULL;
    Node *cur = head;
    int step = 0;
    while (cur != NULL) {
        Node *next = cur->next;    /* ① 先存后继 */

        printf("step %d: ", ++step);
        show("prev", prev);
        printf(" ");
        show("cur", cur);
        printf(" ");
        show("next", next);
        printf("\n");

        cur->next = prev;          /* ② 掉头 */
        prev = cur;                /* ③ prev 前进 */
        cur = next;                /* ④ cur 前进 */
    }
    head = prev;                   /* 循环结束时 prev 就是新表头 */

    if (head == NULL) {
        printf("head=NONE\n");
        printf("list=EMPTY\n");
        return 0;
    }

    printf("head=%d\n", head->value);

    printf("list=");
    int first = 1;
    for (const Node *p = head; p != NULL; p = p->next) {
        if (!first) {
            printf(" ");
        }
        printf("%d", p->value);
        first = 0;
    }
    printf("\n");

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

