#include <stdio.h>

#define MAXN 60000

typedef struct {
    int id;
    int score;
} Rec;

static Rec a[MAXN];
static Rec tmp[MAXN];
static long long inv;

/* 归并排序 [lo, hi)，同时统计逆序对 */
static void merge_sort(int lo, int hi) {
    if (hi - lo <= 1) {
        return;
    }
    int mid = lo + (hi - lo) / 2;
    merge_sort(lo, mid);
    merge_sort(mid, hi);

    int i = lo;
    int j = mid;
    int k = lo;
    while (i < mid && j < hi) {
        if (a[i].score <= a[j].score) {         /* <= ：同分取左边 → 稳定 */
            tmp[k++] = a[i++];
        } else {
            inv += mid - i;                     /* 左半区剩下的都比 a[j] 大 */
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) {
        tmp[k++] = a[i++];
    }
    while (j < hi) {
        tmp[k++] = a[j++];
    }
    for (int t = lo; t < hi; t++) {
        a[t] = tmp[t];                          /* 必须拷回去 */
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d %d", &a[i].id, &a[i].score) != 2) {
            return 0;
        }
        if (a[i].id < 1 || a[i].id > n) {
            return 0;
        }
    }

    inv = 0;
    merge_sort(0, n);

    printf("inv=%lld\n", inv);
    printf("median=%d\n", a[(n + 1) / 2 - 1].score);

    long long chk = 0;
    for (int i = 0; i < n; i++) {
        chk += (long long)(i + 1) * a[i].id;
    }
    printf("chk=%lld\n", chk);

    int q;
    if (scanf("%d", &q) != 1 || q < 1 || q > 1000) {
        return 0;
    }
    for (int i = 0; i < q; i++) {
        int p;
        if (scanf("%d", &p) != 1 || p < 1 || p > n) {
            return 0;
        }
        printf("rank %d %d\n", p, a[p - 1].id);
    }
    return 0;
}

