#include <stdio.h>
#include <string.h>

#define MAXC 1000

int main(void) {
    int capacity = 0;
    int q = 0;
    if (scanf("%d %d", &capacity, &q) != 2 || capacity < 1 || capacity > MAXC || q < 1 || q > 1000) {
        return 0;
    }

    int data[MAXC + 1];      /* 留一个空位：slots = capacity + 1 */
    int slots = capacity + 1;
    int front = 0;           /* 队头元素下标 */
    int rear = 0;            /* 下一个入队位置 */

    for (int i = 0; i < q; i++) {
        char cmd[8];
        if (scanf("%7s", cmd) != 1) {
            return 0;
        }
        if (strcmp(cmd, "push") == 0) {
            int value = 0;
            if (scanf("%d", &value) != 1) {
                return 0;
            }
            if ((rear + 1) % slots == front) {
                printf("push full\n");
            } else {
                data[rear] = value;
                rear = (rear + 1) % slots;
                printf("push ok\n");
            }
        } else if (strcmp(cmd, "pop") == 0) {
            if (front == rear) {
                printf("pop empty\n");
            } else {
                printf("pop %d\n", data[front]);
                front = (front + 1) % slots;
            }
        } else if (strcmp(cmd, "front") == 0) {
            if (front == rear) {
                printf("front empty\n");
            } else {
                printf("front %d\n", data[front]);
            }
        } else if (strcmp(cmd, "size") == 0) {
            printf("size %d\n", (rear - front + slots) % slots);
        }
    }
    return 0;
}

