} Node;

typedef struct {
    Node *head;      /* 队头 */
    Node *tail;      /* 队尾 */
    int size;
} Queue;

static int enqueue(Queue *q, int r, int c, int dist) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->r = r;
    node->c = c;
    node->dist = dist;
    node->next = NULL;
    if (q->tail == NULL) {
        q->head = node;
        q->tail = node;
    } else {
        q->tail->next = node;
        q->tail = node;
    }
    q->size++;
    return 1;
}

static int dequeue(Queue *q, int *r, int *c, int *dist) {
    if (q->head == NULL) {
        return 0;
    }
    Node *node = q->head;
    q->head = node->next;
    if (q->head == NULL) {
        q->tail = NULL;          /* 出队到空时必须清 tail */
    }
    q->size--;
    *r = node->r;
    *c = node->c;
    *dist = node->dist;
    free(node);
    return 1;
}

int main(void) {
    int rows = 0;
    int cols = 0;
    if (scanf("%d %d", &rows, &cols) != 2 || rows < 1 || rows > MAXR || cols < 1 || cols > MAXC) {
        return 0;
    }

    char grid[MAXR][MAXC + 1];
    for (int i = 0; i < rows; i++) {
        if (scanf("%200s", grid[i]) != 1) {
            return 0;
        }
    }

    int start_r = -1;
    int start_c = -1;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 'S') {
                start_r = r;
                start_c = c;
            }
        }
    }
    if (start_r < 0) {
        return 0;
    }

