            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            if (grid[nr][nc] == '#' || seen[nr][nc]) {
                continue;
            }
            seen[nr][nc] = 1;
            if (enqueue(&q, nr, nc, d + 1)) {
                visited++;
                if (q.size > peak) {
                    peak = q.size;
                }
            }
        }
    }

    if (best < 0) {
        printf("dist=none\n");
    } else {
        printf("dist=%d\n", best);
    }
