        for (int i = p + 1; i < n; i++) {
            if (work[i] <= work[p]) {
                prop_ok = 0;
            }
        }
    }
    int same_ok = same_multiset(work, orig, n);
    printf("part_index=%d\n", p);
    printf("part_pivot_ok=%d\n", pivot_ok);
    printf("part_prop_ok=%d\n", prop_ok);
    printf("part_same_ok=%d\n", same_ok);

    /* ---------- 2. 三路划分 ---------- */
    for (int i = 0; i < n; i++) {
