    for (int i = 0; i < n && i < 5; i++) {
        printf("%s%d", i ? " " : "", work[i]);
    }
    printf("\n");
    printf("sorted_tail=");
    int start = (n > 5) ? n - 5 : 0;
    for (int i = start; i < n; i++) {
        printf("%s%d", (i == start) ? "" : " ", work[i]);
    }
    printf("\n");
    return 0;
}

