#include "sorting.h"

static void swap_int(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int qs_partition(int *a, int lo, int hi) {
    int pivot = a[hi];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (a[j] <= pivot) {
            swap_int(&a[i], &a[j]);
            i++;
        }
    }
    swap_int(&a[i], &a[hi]);
    return i;
}

void qs_partition3(int *a, int lo, int hi, int *lt, int *gt) {
    int pivot = a[lo];
    int left = lo;
    int i = lo + 1;
    int right = hi;
    while (i <= right) {
        if (a[i] < pivot) {
            swap_int(&a[left], &a[i]);
            left++;
            i++;
        } else if (a[i] > pivot) {
            swap_int(&a[i], &a[right]);
            right--;
        } else {
            i++;
        }
    }
    if (lt != 0) {
        *lt = left;
    }
    if (gt != 0) {
        *gt = right;
    }
}

/* 错：直接用 Lomuto 递归，全等数组退化成 O(n²) */
static void sort_range(int *a, int lo, int hi) {
    if (lo >= hi) {
        return;
    }
    int p = qs_partition(a, lo, hi);
    sort_range(a, lo, p - 1);
    sort_range(a, p + 1, hi);
}

void qs_sort(int *a, int lo, int hi) {
    sort_range(a, lo, hi);
}

