hints:
先写"按序插入一个节点"，它是全题的核心：

```c
Node **link = head;
while (*link != NULL && (*link)->id < id) {
    link = &(*link)->next;
}
```

循环结束时 `*link` 是"第一个学号大于等于 id 的节点"或者 `NULL`。此时如果 `*link != NULL && (*link)->id == id`，说明学号重复，直接返回（**不要**建节点）；否则新节点就插在 `*link` 前面。

用二级指针 `Node **` 传 `head`，上面那段代码就同时覆盖了三种位置：插到表头（`link == head`）、插到中间、插到末尾（`*link == NULL`）。插入动作只有两句：

```c
node->next = *link;
*link = node;
```

删除同理：走到 `*link` 是目标节点后，`*link = dead->next; free(dead);`。

reference.main.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_MAX 16

typedef struct Node {
    int id;
    char name[NAME_MAX];
    struct Node *next;
} Node;

static int list_count(const Node *head) {
    int n = 0;
    for (const Node *p = head; p != NULL; p = p->next) {
        n++;
    }
    return n;
}

/* 按学号升序插入；学号已存在时忽略并返回 0 */
static int insert_sorted(Node **head, int id, const char *name) {
    Node **link = head;
    while (*link != NULL && (*link)->id < id) {
        link = &(*link)->next;
    }
    if (*link != NULL && (*link)->id == id) {
        return 0;                     /* 重复学号：不建节点，直接忽略 */
    }
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->id = id;
    strncpy(node->name, name, sizeof node->name - 1);
    node->name[sizeof node->name - 1] = '\0';
    node->next = *link;
    *link = node;
    return 1;
}

static int remove_id(Node **head, int id) {
    Node **link = head;
    while (*link != NULL && (*link)->id != id) {
        link = &(*link)->next;
    }
    if (*link == NULL) {
        return 0;
    }
    Node *dead = *link;
    *link = dead->next;               /* 先摘链 */
    free(dead);                       /* 再释放 */
    return 1;
}

static int destroy(Node **head) {
    int freed = 0;
    Node *p = *head;
    while (p != NULL) {
        Node *next = p->next;
        free(p);
        p = next;
        freed++;
    }
    *head = NULL;
    return freed;
}

static void print_list(const char *label, const Node *head) {
    printf("%s %d", label, list_count(head));
    for (const Node *p = head; p != NULL; p = p->next) {
        printf(" %d:%s", p->id, p->name);
    }
    printf("\n");
}

int main(void) {
    Node *head = NULL;

    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 500) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        int id;
        char name[NAME_MAX];
        if (scanf("%d %15s", &id, name) != 2) {
            destroy(&head);
            return 0;
        }
        insert_sorted(&head, id, name);
    }

    int m;
    if (scanf("%d", &m) != 1 || m < 0 || m > 200) {
        destroy(&head);
        return 0;
    }
    for (int i = 0; i < m; i++) {
        int id;
        char name[NAME_MAX];
        if (scanf("%d %15s", &id, name) != 2) {
            destroy(&head);
            return 0;
        }
        insert_sorted(&head, id, name);
    }

    print_list("roster", head);

    int k;
    if (scanf("%d", &k) != 1 || k < 0 || k > 200) {
        destroy(&head);
        return 0;
    }
    int removed = 0;
    for (int i = 0; i < k; i++) {
        int id;
        if (scanf("%d", &id) != 1) {
            break;
        }
        if (remove_id(&head, id)) {
            removed++;
        }
    }

    printf("removed=%d\n", removed);
    print_list("after", head);

    int freed = destroy(&head);
    printf("freed=%d\n", freed);
    return 0;
}

