#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    long long value;
    struct Node *next;
} Node;

typedef struct {
    Node *top;      /* 链表头就是栈顶 */
    int size;
} Stack;

static int stack_push(Stack *s, long long value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->value = value;
    node->next = s->top;
    s->top = node;
    s->size++;
    return 1;
}

static int stack_pop(Stack *s, long long *out) {
    if (s->top == NULL) {
        return 0;
    }
    Node *node = s->top;
    s->top = node->next;
    s->size--;
    *out = node->value;
    free(node);
    return 1;
}

static void stack_destroy(Stack *s) {
    long long value = 0;
    while (stack_pop(s, &value)) {
        /* 一直弹到空，节点就全部释放了 */
    }
}

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1 || n < 1 || n > 2000) {
        return 0;
    }

    Stack s = { NULL, 0 };
    int max_depth = 0;
    int ops = 0;
    int ok = 1;

    for (int i = 0; i < n; i++) {
        char token[32];
        if (scanf("%31s", token) != 1) {
            ok = 0;
            break;
        }

        int is_op = (strlen(token) == 1) &&
                    (token[0] == '+' || token[0] == '-' || token[0] == '*');
        if (is_op) {
            long long right = 0;
            long long left = 0;
            if (!stack_pop(&s, &right) || !stack_pop(&s, &left)) {
                ok = 0;
                break;
            }
            long long value = 0;
            if (token[0] == '+') {
                value = left + right;
            } else if (token[0] == '-') {
                value = left - right;          /* 后弹出的是左操作数 */
            } else {
                value = left * right;
            }
            if (!stack_push(&s, value)) {
                ok = 0;
                break;
            }
            ops++;
        } else {
            long long value = strtoll(token, NULL, 10);
            if (!stack_push(&s, value)) {
                ok = 0;
                break;
            }
        }

        if (s.size > max_depth) {
            max_depth = s.size;
        }
    }

    long long result = 0;
    if (ok && s.size == 1) {
        stack_pop(&s, &result);
    } else {
        ok = 0;
    }
    stack_destroy(&s);

    printf("result=%lld\n", result);
    printf("depth_max=%d\n", max_depth);
    printf("ops=%d\n", ops);
    return 0;
}

