code.main.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

typedef struct {
    Node *top;
    int size;
} Stack;

static int stack_push(Stack *s, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return 0;
    }
    node->value = value;
    node->next = s->top;
    s->top = node;
    s->size++;
    return 1;
}

static int stack_pop(Stack *s, int *out) {
    if (s->top == NULL) {
        return 0;
    }
    Node *node = s->top;
    s->top = node->next;
    s->size--;
    *out = node->value;
    free(node);
    return 1;
}

static void stack_destroy(Stack *s) {
    int value = 0;
    while (stack_pop(s, &value)) {
    }
}

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    Stack s = { NULL, 0 };
    int max_depth = 0;
    int ops = 0;

    for (int i = 0; i < n; i++) {
        char token[32];
        if (scanf("%31s", token) != 1) {
            break;
        }
        int is_op = (strlen(token) == 1) &&
                    (token[0] == '+' || token[0] == '-' || token[0] == '*');
        if (is_op) {
            int right = 0;
            int left = 0;
            stack_pop(&s, &right);
            stack_pop(&s, &left);
            int value = 0;
            if (token[0] == '+') {
                value = left + right;
            } else if (token[0] == '-') {
                value = left - right;
            } else {
                value = left * right;       /* 错：int 相乘会溢出 */
            }
            stack_push(&s, value);
            ops++;
        } else {
            stack_push(&s, (int)strtoll(token, NULL, 10));
        }
        if (s.size > max_depth) {
            max_depth = s.size;
        }
    }

    int result = 0;
    stack_pop(&s, &result);
    stack_destroy(&s);
    printf("result=%d\n", result);
    printf("depth_max=%d\n", max_depth);
    printf("ops=%d\n", ops);
    return 0;
}

